{"command":"cat > flags.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Flag definitions in canonical order (for __complete "-" listing).
type flagDef struct {
	long    string
	short   byte // 0 if none
	isBool  bool
	usage   string
}

var flagDefs = []flagDef{
	{"all", 'a', true, "Search among all cheatpaths"},
	{"brief", 'b', true, "List cheatsheets without file paths"},
	{"colorize", 'c', true, "Colorize output"},
	{"completion", 0, false, "Generate shell completion script (`shell`: bash, zsh, fish, powershell)"},
	{"conf", 0, true, "Display the config file path"},
	{"directories", 'd', true, "List cheatsheet directories"},
	{"edit", 'e', false, "Edit `cheatsheet`"},
	{"help", 'h', true, "help for cheat"},
	{"init", 0, true, "Write a default config file to stdout"},
	{"list", 'l', true, "List cheatsheets"},
	{"path", 'p', false, "Return only sheets found on cheatpath `name`"},
	{"regex", 'r', true, "Treat search <phrase> as a regex"},
	{"rm", 0, false, "Remove (delete) `cheatsheet`"},
	{"search", 's', false, "Search cheatsheets for `phrase`"},
	{"tag", 't', false, "Return only sheets matching `tag`"},
	{"tags", 'T', true, "List all tags in use"},
	{"update", 'u', true, "Update git-backed cheatpaths"},
	{"version", 'v', true, "Print the version number"},
}

var byLong map[string]*flagDef
var byShort map[byte]*flagDef

func init() {
	byLong = map[string]*flagDef{}
	byShort = map[byte]*flagDef{}
	for i := range flagDefs {
		d := &flagDefs[i]
		byLong[d.long] = d
		if d.short != 0 {
			byShort[d.short] = d
		}
	}
}

func boolFlagLabel(d *flagDef) string {
	if d.short != 0 {
		return fmt.Sprintf("\"-%c, --%s\"", d.short, d.long)
	}
	return fmt.Sprintf("\"--%s\"", d.long)
}

// parsedArgs holds the result of pflag-compatible parsing.
type parsedArgs struct {
	bools       map[string]bool
	strings     map[string]string
	changed     map[string]bool
	positionals []string
	// consumed[i] is true if argv[i] was consumed as a flag value.
	consumed []bool
	// bareHelpIdx are argv indices of standalone "-h"/"--help" parsed as flags.
	bareHelp []int
}

func newParsedArgs(n int) *parsedArgs {
	return &parsedArgs{
		bools:    map[string]bool{},
		strings:  map[string]string{},
		changed:  map[string]bool{},
		consumed: make([]bool, n),
	}
}

// parseParent performs full pflag parsing with blind value consumption and
// bool validation. Returns error with exact pflag messages.
func parseParent(argv []string) (*parsedArgs, error) {
	p := newParsedArgs(len(argv))
	args := argv
	// work on indices
	i := 0
	for i < len(args) {
		tok := args[i]
		if tok == "--" {
			// rest are positionals
			for j := i + 1; j < len(args); j++ {
				p.positionals = append(p.positionals, args[j])
			}
			break
		}
		if len(tok) >= 2 && tok[0] == '-' && tok[1] == '-' {
			// long flag
			name := tok[2:]
			var val string
			hasVal := false
			if idx := strings.IndexByte(name, '='); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}
			d := byLong[name]
			if d == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if d.isBool {
				if hasVal {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return nil, fmt.Errorf("invalid argument %q for %s flag: %v", val, boolFlagLabel(d), err)
					}
					p.bools[d.long] = b
				} else {
					p.bools[d.long] = true
				}
				p.changed[d.long] = true
				if (tok == "-h" || tok == "--help") && d.long == "help" {
					p.bareHelp = append(p.bareHelp, i)
				}
				i++
				continue
			}
			// string flag
			if hasVal {
				p.strings[d.long] = val
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				p.strings[d.long] = args[i]
				p.consumed[i] = true
			}
			p.changed[d.long] = true
			i++
			continue
		}
		if len(tok) >= 2 && tok[0] == '-' {
			// short bundle
			sh := tok[1:]
			j := 0
			for j < len(sh) {
				c := sh[j]
				d := byShort[c]
				if d == nil {
					return nil, fmt.Errorf("unknown shorthand flag: '%c' in -%s", c, sh[j:])
				}
				if d.isBool {
					// =-form? needs len>2 of remaining and [1]=='='
					rest := sh[j:]
					if len(rest) > 2 && rest[1] == '=' {
						v := rest[2:]
						b, err := strconv.ParseBool(v)
						if err != nil {
							return nil, fmt.Errorf("invalid argument %q for %s flag: %v", v, boolFlagLabel(d), err)
						}
						p.bools[d.long] = b
						p.changed[d.long] = true
						// whole token consumed
						j = len(sh)
						break
					}
					p.bools[d.long] = true
					p.changed[d.long] = true
					if tok == "-h" && d.long == "help" {
						p.bareHelp = append(p.bareHelp, i)
					}
					j++
					continue
				}
				// value flag: rest of token is value (verbatim, incl '=')
				rest := sh[j+1:]
				if rest != "" {
					p.strings[d.long] = rest
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: '%c' in -%c", c, c)
					}
					i++
					p.strings[d.long] = args[i]
					p.consumed[i] = true
				}
				p.changed[d.long] = true
				// value flag ends bundle
				j = len(sh)
				break
			}
			i++
			continue
		}
		// positional
		p.positionals = append(p.positionals, tok)
		i++
	}
	return p, nil
}

// stripResult is the outcome of the routing strip pass.
type stripResult struct {
	// firstPosIdx is the argv index of the first positional, or -1.
	firstPosIdx int
	firstPos    string
	// bareHelp indices of standalone -h/--help parsed as flags before firstPosIdx.
	bareHelp []int
	// consumed marks argv entries consumed as values during strip.
	consumed []bool
}

// stripArgs walks tokens like parseParent but skips bool validation; it stops
// at the first positional. Unknown flags and missing values are errors.
func stripArgs(argv []string) (*stripResult, error) {
	r := &stripResult{firstPosIdx: -1, consumed: make([]bool, len(argv))}
	i := 0
	for i < len(argv) {
		tok := argv[i]
		if tok == "--" {
			if i+1 < len(argv) {
				r.firstPosIdx = i + 1
				r.firstPos = argv[i+1]
			}
			return r, nil
		}
		if len(tok) >= 2 && tok[0] == '-' && tok[1] == '-' {
			name := tok[2:]
			hasVal := false
			if idx := strings.IndexByte(name, '='); idx >= 0 {
				name = name[:idx]
				hasVal = true
			}
			d := byLong[name]
			if d == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if d.isBool {
				if tok == "--help" {
					r.bareHelp = append(r.bareHelp, i)
				}
				i++
				continue
			}
			if hasVal {
				i++
				continue
			}
			if i+1 >= len(argv) {
				return nil, fmt.Errorf("flag needs an argument: --%s", name)
			}
			i++
			r.consumed[i] = true
			i++
			continue
		}
		if len(tok) >= 2 && tok[0] == '-' {
			sh := tok[1:]
			j := 0
			for j < len(sh) {
				c := sh[j]
				d := byShort[c]
				if d == nil {
					return nil, fmt.Errorf("unknown shorthand flag: '%c' in -%s", c, sh[j:])
				}
				if d.isBool {
					rest := sh[j:]
					if len(rest) > 2 && rest[1] == '=' {
						j = len(sh)
						break
					}
					if tok == "-h" {
						r.bareHelp = append(r.bareHelp, i)
					}
					j++
					continue
				}
				rest := sh[j+1:]
				if rest != "" {
					j = len(sh)
					break
				}
				if i+1 >= len(argv) {
					return nil, fmt.Errorf("flag needs an argument: '%c' in -%c", c, c)
				}
				i++
				r.consumed[i] = true
				j = len(sh)
				break
			}
			i++
			continue
		}
		r.firstPosIdx = i
		r.firstPos = tok
		return r, nil
	}
	return r, nil
}
EOF
