	// Strip pass: routing + unknown/missing errors.
	st, err := stripArgs(argv)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}
	if st.firstPos == "__complete" && st.firstPosIdx >= 0 {
		// Parent help short-circuits routing (bare -h/--help before token).
		for _, idx := range st.bareHelp {
			if idx < st.firstPosIdx {
				fmt.Fprint(os.Stdout, helpText)
				return 0
			}
		}
		// Route to __complete with the token removed.
		cargs := make([]string, 0, len(argv)-1)
		for i, t := range argv {
			if i == st.firstPosIdx {
				continue
			}
			cargs = append(cargs, t)
		}
		return runComplete(cargs)
	}

	// Full parent parse.
	p, err := parseParent(argv)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}
	// Help beats args validation.
	if p.changed["help"] {
		fmt.Fprint(os.Stdout, helpText)
		return 0
	}
	if len(p.positionals) > 1 {
		fmt.Fprintf(os.Stderr, "accepts at most 1 arg(s), received %d\n", len(p.positionals))
		return 1
	}
	// No-config actions.
	if p.bools["init"] {
		return cmdInit()
	}
	if p.bools["version"] {
		fmt.Fprintln(os.Stdout, version)
		return 0
	}
	if p.changed["completion"] {
		return cmdCompletion(p.strings["completion"])
	}

	// Everything else needs config (installer on missing).
	cfg, cfgPath, st := loadConfigOrInstall()
	if st == cfgDeclined {
		return 0
	}
	if st == cfgInstalled {
		return 0
	}
	if st != cfgOK {
		// error already printed
		return 1
	}

	return dispatch(cfg, cfgPath, p)
}

func cmdCompletion(shell string) int {
	var s_ string
	switch shell {
	case "bash":
		s_ = compBash
	case "zsh":
		s_ = compZsh
	case "fish":
		s_ = compFish
	case "powershell":
		s_ = compPowershell
	default:
		fmt.Fprintf(os.Stderr, "unsupported shell: %s (valid: bash, zsh, fish, powershell)\n", shell)
		return 1
	}
	fmt.Fprint(os.Stdout, s_)
	return 0
}
