// parseBlock parses a block node (map or seq) starting at line start, with
// parent indent parentIndent. Lines in [start, end).
func (p *yParser) parseBlock(start, end, parentIndent int) (*yNode, int, error) {
	// determine indent of first content line
	i := start
	for i < end && isBlankOrComment(p.lines[i]) {
		i++
	}
	if i >= end {
		return nil, i, nil
	}
	ind := indentOf(p.lines[i])
	if ind <= parentIndent {
		return nil, i, nil
	}
	trimmed := strings.TrimSpace(p.lines[i])
	if isSeqItem(trimmed) {
		return p.parseSeq(i, end, ind)
	}
	return p.parseMap(i, end, ind)
}

func isSeqItem(trimmed string) bool {
	return trimmed == "-" || strings.HasPrefix(trimmed, "- ") || strings.HasPrefix(trimmed, "-\t")
}

// parseSeq parses a block sequence at indent ind.
func (p *yParser) parseSeq(start, end, ind int) (*yNode, int, error) {
	node := &yNode{kind: ySeq, line: start + 1}
	i := start
	for i < end {
		if isBlankOrComment(p.lines[i]) {
			i++
			continue
		}
		curInd := indentOf(p.lines[i])
		if curInd < ind {
			break
		}
		if curInd > ind {
			return nil, i, &yError{i + 1, "did not find expected '-' indicator"}
		}
		trimmed := strings.TrimSpace(p.lines[i])
		if !isSeqItem(trimmed) {
			// Could be a map key at same level -> end of seq (caller handles as error or map?)
			// In block context `- a` then `b: c` at same indent is invalid; return seq and let caller error.
			break
		}
		lineNo := i + 1
		// content after '-'
		rest := strings.TrimPrefix(p.lines[i][ind:], "-")
		if len(rest) > 0 && (rest[0] == ' ' || rest[0] == '\t') {
			rest = rest[1:]
		}
		rest = stripComment(rest)
		restTrim := strings.TrimSpace(rest)
		i++
		if restTrim == "" {
			// nested block or null
			j := i
			for j < end && isBlankOrComment(p.lines[j]) {
				j++
			}
			if j < end && indentOf(p.lines[j]) > ind {
				child, next, err := p.parseBlock(j, end, ind)
				if err != nil {
					return nil, j, err
				}
				if child == nil {
					node.items = append(node.items, &yNode{kind: yScalar, line: lineNo})
				} else {
					node.items = append(node.items, child)
				}
				i = next
				continue
			}
			node.items = append(node.items, &yNode{kind: yScalar, line: lineNo})
			continue
		}
		// inline content: could be scalar/flow, or start of a map (key: ...)
		// Check for block scalar header or anchor/tag-only then nested.
		if restTrim == "|" || restTrim == ">" || strings.HasPrefix(restTrim, "|") || strings.HasPrefix(restTrim, ">") {
