			sc, next, err := p.parseBlockScalar(i, end, ind, restTrim, lineNo)
			if err != nil {
				return nil, i, err
			}
			node.items = append(node.items, sc)
			i = next
			continue
		}
		// anchor/tag handling
		rest2, anchor, tag, okAnchor := splitAnchorTag(restTrim)
		_ = okAnchor
		if anchor != "" || tag != "" {
			if rest2 == "" {
				// anchor on nested block
				j := i
				for j < end && isBlankOrComment(p.lines[j]) {
					j++
				}
				if j < end && indentOf(p.lines[j]) > ind {
					child, next, err := p.parseBlock(j, end, ind)
					if err != nil {
						return nil, j, err
					}
					if anchor != "" && child != nil {
						p.anchors[anchor] = child
					}
					if child == nil {
						node.items = append(node.items, &yNode{kind: yScalar, line: lineNo})
					} else {
						node.items = append(node.items, child)
					}
					i = next
					continue
				}
				nd := &yNode{kind: yScalar, line: lineNo}
				if anchor != "" {
					p.anchors[anchor] = nd
				}
				node.items = append(node.items, nd)
				continue
			}
			// anchor + inline value
			nd, err := p.parseInlineValue(rest2, lineNo, i, end, ind)
			if err != nil {
				return nil, i - 1, err
			}
			nd, err = p.maybeContinue(nd, rest2, &i, end, ind, lineNo)
			if err != nil {
				return nil, i, err
			}
			if anchor != "" {
				p.anchors[anchor] = nd
			}
			if tag != "" {
				nd.tag = tag
			}
			node.items = append(node.items, nd)
			continue
		}
		// alias?
		if strings.HasPrefix(restTrim, "*") {
			name := strings.TrimSpace(restTrim[1:])
			target, ok := p.anchors[name]
			if !ok {
				return nil, i - 1, &yError{lineNo, fmt.Sprintf("unknown anchor '%s' referenced", name)}
			}
			node.items = append(node.items, target)
			continue
		}
		// inline map? `- key: value`
		if mkey, mrest, ok := splitMapKey(restTrim); ok {
			mnode := &yNode{kind: yMap, line: lineNo}
			if err := p.addMapEntry(mnode, mkey, mrest, lineNo, &i, end, ind, ind); err != nil {
				return nil, i, err
			}
			// continuation lines: more map entries at indent > ind (nested under this item)
			for {
				j := i
				for j < end && isBlankOrComment(p.lines[j]) {
					j++
				}
				if j >= end || indentOf(p.lines[j]) <= ind {
					break
				}
				// must be map entries (not seq items)
				jt := strings.TrimSpace(p.lines[j])
				if isSeqItem(jt) {
					break
				}
				mk, mr, ok := splitMapKey(stripComment(strings.TrimSpace(p.lines[j][indentOf(p.lines[j]):])))
				if !ok {
					break
				}
				_ = mk
				_ = mr
				_ = jt
				// parse as map at that indent, merging into mnode
				sub, next, err := p.parseMap(j, end, ind)
				if err != nil {
					return nil, j, err
				}
				// merge sub entries into mnode
				for k := range sub.keys {
					mnode.keys = append(mnode.keys, sub.keys[k])
					mnode.vals = append(mnode.vals, sub.vals[k])
				}
				i = next
				break // parseMap consumed all at that level
			}
			node.items = append(node.items, mnode)
			continue
		}
		nd, err := p.parseInlineValue(restTrim, lineNo, i, end, ind)
		if err != nil {
			return nil, i - 1, err
		}
		nd, err = p.maybeContinue(nd, restTrim, &i, end, ind, lineNo)
		if err != nil {
			return nil, i, err
		}
		node.items = append(node.items, nd)
	}
	return node, i, nil
}

// maybeContinue handles multi-line plain/quoted scalars and flow spanning lines.
func (p *yParser) maybeContinue(nd *yNode, first string, i *int, end, ind, lineNo int) (*yNode, error) {
	if nd.kind != yScalar {
		// flow node possibly incomplete (multi-line flow)?
		if fe, ok := nd.tagFlowIncomplete(); ok && fe {
			// continue reading lines until flow closes
			_ = ok
		}
		return nd, nil
	}
	// If scalar was quoted, check if quote closed on same line.
	if nd.quoted {
		// quoted scalars that didn't close: need continuation (handled in parseInlineValue? no).
		// For simplicity, quoted multiline handled here.
		if !nd.closed {
			// accumulate
			parts := []string{nd.text}
			q := nd.quoteChar
			for *i < end {
				if isBlankOrComment(p.lines[*i]) {
					// blank line inside quoted scalar -> newline?
					*i++
					parts = append(parts, "")
					continue
				}
				if indentOf(p.lines[*i]) <= ind {
					return nil, &yError{lineNo, "found unexpected end of stream"}
				}
				ln := strings.TrimSpace(p.lines[*i])
				*i++
				// find closing quote
				s, closed, err := scanQuoted(ln, q, lineNo)
				if err != nil {
					return nil, err
				}
				parts = append(parts, s)
				if closed {
					break
				}
			}
			nd.text = foldQuoted(parts, q)
			nd.closed = true
		}
		return nd, nil
	}
	// plain scalar: continuation lines (deeper indent, not key/seq/flow starts)
	parts := []string{nd.text}
	for {
		j := *i
		for j < end && isBlankOrComment(p.lines[j]) {
			j++
		}
		if j >= end {
			break
		}
		if indentOf(p.lines[j]) <= ind {
			break
		}
		ln := strings.TrimSpace(p.lines[j])
		// stop at seq item, flow starts, block scalar headers, anchors? (plain continues otherwise)
		if isSeqItem(ln) {
			break
		}
		if strings.HasPrefix(ln, "[") || strings.HasPrefix(ln, "{") || strings.HasPrefix(ln, "|") || strings.HasPrefix(ln, ">") || strings.HasPrefix(ln, "&") || strings.HasPrefix(ln, "*") || strings.HasPrefix(ln, "!") {
			break
		}
		// a 'key:' line at deeper indent: is it continuation or nested map?
		// If current context is a value, deeper 'key:' is an error in strict YAML,
		// but we treat as end of scalar (caller will error appropriately).
		if _, _, ok := splitMapKey(stripComment(ln)); ok {
			break
		}
		// check for blank lines between (paragraph breaks -> newlines?) - simplify: fold with space
		*i = j + 1
		parts = append(parts, stripComment(ln))
	}
	if len(parts) > 1 {
		nd.text = strings.Join(parts, " ")
	}
	return nd, nil
}
