					}
					if anchor != "" && child != nil {
						p.anchors[anchor] = child
					}
					if child == nil {
						node.items = append(node.items, &yNode{kind: yScalar, line: lineNo})
					} else {
						node.items = append(node.items, child)
					}
					i = next
					continue
				}
				nd := &yNode{kind: yScalar, line: lineNo}
				if anchor != "" {
					p.anchors[anchor] = nd
				}
				node.items = append(node.items, nd)
				continue
			}
