		if err != nil {
			return nil, i - 1, err
		}
		nd, err = p.maybeContinue(nd, restTrim, &i, end, ind, lineNo)
		if err != nil {
			return nil, i, err
		}
		node.items = append(node.items, nd)
	}
	return node, i, nil
}

// maybeContinue handles multi-line plain/quoted scalars and flow spanning lines.
func (p *yParser) maybeContinue(nd *yNode, first string, i *int, end, ind, lineNo int) (*yNode, error) {
	if nd.kind != yScalar {
		// flow node possibly incomplete (multi-line flow)?
		if fe, ok := nd.tagFlowIncomplete(); ok && fe {
			// continue reading lines until flow closes
			_ = ok
		}
		return nd, nil
	}
	// If scalar was quoted, check if quote closed on same line.
	if nd.quoted {
		// quoted scalars that didn't close: need continuation (handled in parseInlineValue? no).
		// For simplicity, quoted multiline handled here.
		if !nd.closed {
			// accumulate
			parts := []string{nd.text}
			q := nd.quoteChar
			for *i < end {
				if isBlankOrComment(p.lines[*i]) {
					// blank line inside quoted scalar -> newline?
					*i++
					parts = append(parts, "")
					continue
				}
				if indentOf(p.lines[*i]) <= ind {
					return nil, &yError{lineNo, "found unexpected end of stream"}
				}
				ln := strings.TrimSpace(p.lines[*i])
				*i++
				// find closing quote
				s, closed, err := scanQuoted(ln, q, lineNo)
				if err != nil {
					return nil, err
				}
				parts = append(parts, s)
				if closed {
					break
				}
			}
			nd.text = foldQuoted(parts, q)
			nd.closed = true
		}
		return nd, nil
	}
	// plain scalar: continuation lines (deeper indent, not key/seq/flow starts)
	parts := []string{nd.text}
	for {
		j := *i
		for j < end && isBlankOrComment(p.lines[j]) {
			j++
		}
		if j >= end {
			break
		}
		if indentOf(p.lines[j]) <= ind {
			break
		}
		ln := strings.TrimSpace(p.lines[j])
		// stop at seq item, flow starts, block scalar headers, anchors? (plain continues otherwise)
		if isSeqItem(ln) {
			break
		}
		if strings.HasPrefix(ln, "[") || strings.HasPrefix(ln, "{") || strings.HasPrefix(ln, "|") || strings.HasPrefix(ln, ">") || strings.HasPrefix(ln, "&") || strings.HasPrefix(ln, "*") || strings.HasPrefix(ln, "!") {
			break
		}
		// a 'key:' line at deeper indent: is it continuation or nested map?
		// If current context is a value, deeper 'key:' is an error in strict YAML,
		// but we treat as end of scalar (caller will error appropriately).
		if _, _, ok := splitMapKey(stripComment(ln)); ok {
			break
		}
		// check for blank lines between (paragraph breaks -> newlines?) - simplify: fold with space
		*i = j + 1
		parts = append(parts, stripComment(ln))
	}
	if len(parts) > 1 {
		nd.text = strings.Join(parts, " ")
	}
	return nd, nil
}
