func isBlockHeader(s string) bool {
	if s == "" || (s[0] != '|' && s[0] != '>') {
		return false
	}
	// rest must be chomping/indent indicators only
	for i := 1; i < len(s); i++ {
		c := s[i]
		if c == '-' || c == '+' || (c >= '1' && c <= '9') {
			continue
		}
		return false
	}
	return true
}

// splitAnchorTag splits leading &anchor and !!tag (in any order) from s.
func splitAnchorTag(s string) (rest, anchor, tag string, ok bool) {
	rest = strings.TrimSpace(s)
	for {
		if strings.HasPrefix(rest, "&") {
			j := 1
			for j < len(rest) && rest[j] != ' ' && rest[j] != '\t' {
				j++
			}
			anchor = rest[1:j]
			rest = strings.TrimSpace(rest[j:])
			ok = true
			continue
		}
		if strings.HasPrefix(rest, "!!") || strings.HasPrefix(rest, "!") {
			j := 1
			if strings.HasPrefix(rest, "!!") {
				j = 2
			}
			for j < len(rest) && rest[j] != ' ' && rest[j] != '\t' {
				j++
			}
			tag = rest[:j]
			rest = strings.TrimSpace(rest[j:])
			ok = true
			continue
		}
		break
	}
	return rest, anchor, tag, ok
}
