// scanQuoted scans a quoted segment within a line starting after opening quote.
// Returns text, closed?, error.
func scanQuoted(ln string, q byte, lineNo int) (string, bool, error) {
	var sb strings.Builder
	i := 0
	for i < len(ln) {
		c := ln[i]
		if q == '"' && c == '\\' {
			if i+1 >= len(ln) {
				sb.WriteByte(c)
				i++
				continue
			}
			sb.WriteByte(c)
			sb.WriteByte(ln[i+1])
			i += 2
			continue
		}
		if c == q {
			if q == '\'' && i+1 < len(ln) && ln[i+1] == '\'' {
				sb.WriteString("''")
				i += 2
				continue
			}
			rest := strings.TrimSpace(ln[i+1:])
			if rest != "" {
				return "", false, &yError{lineNo, "mapping values are not allowed in this context"}
			}
			raw := sb.String()
			if q == '\'' {
				return strings.ReplaceAll(raw, "''", "'"), true, nil
			}
			return unescapeDouble(raw, lineNo), true, nil
		}
