	open := s[0]
	nd, err := fp.parseValue()
	if err != nil {
		return nil, err
	}
	_ = open
	// ensure fully consumed
	fp.skipSpaces()
	if fp.pos < len(fp.s) {
		return nil, &yError{lineNo, "mapping values are not allowed in this context"}
	}
	return nd, nil
}

type flowParser struct {
	s    string
	pos  int
	line int
	p    *yParser
}

func (f *flowParser) skipSpaces() {
	for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t') {
		f.pos++
	}
}

func (f *flowParser) parseValue() (*yNode, error) {
	f.skipSpaces()
	if f.pos >= len(f.s) {
		return &yNode{kind: yScalar, line: f.line}, nil
	}
	c := f.s[f.pos]
	if c == '[' {
		return f.parseSeq()
	}
	if c == '{' {
		return f.parseMap()
	}
	if c == '"' || c == '\'' {
		return f.parseQuoted()
	}
	if c == '&' {
		// anchor
		j := f.pos + 1
		for j < len(f.s) && f.s[j] != ' ' && f.s[j] != '\t' && f.s[j] != ',' && f.s[j] != ']' && f.s[j] != '}' && f.s[j] != ':' {
			j++
		}
		name := f.s[f.pos+1 : j]
		f.pos = j
		f.skipSpaces()
		nd, err := f.parseValue()
		if err != nil {
			return nil, err
		}
		f.p.anchors[name] = nd
		return nd, nil
	}
	if c == '*' {
		j := f.pos + 1
		for j < len(f.s) && f.s[j] != ' ' && f.s[j] != '\t' && f.s[j] != ',' && f.s[j] != ']' && f.s[j] != '}' {
			j++
		}
		name := f.s[f.pos+1 : j]
		f.pos = j
		target, ok := f.p.anchors[name]
		if !ok {
			return nil, &yError{f.line, fmt.Sprintf("unknown anchor '%s' referenced", name)}
		}
		return target, nil
	}
	if c == '!' {
		// tag: skip it
		j := f.pos + 1
		for j < len(f.s) && f.s[j] != ' ' && f.s[j] != '\t' {
			j++
		}
		tag := f.s[f.pos:j]
		f.pos = j
		f.skipSpaces()
		nd, err := f.parseValue()
		if err != nil {
			return nil, err
		}
		if isStdTag(tag) {
			nd.tag = tag
		}
		return nd, nil
	}
	// plain scalar: read until , ] } or : (for map keys, : followed by space/comma/]/})
	start := f.pos
	var inS, inD bool
	for f.pos < len(f.s) {
		ch := f.s[f.pos]
		if inS {
			if ch == '\'' {
				if f.pos+1 < len(f.s) && f.s[f.pos+1] == '\'' {
					f.pos++
				} else {
					inS = false
				}
			}
			f.pos++
			continue
		}
		if inD {
			if ch == '\\' {
				f.pos++
			} else if ch == '"' {
				inD = false
			}
			f.pos++
			continue
		}
		if ch == '\'' {
			inS = true
			f.pos++
			continue
		}
		if ch == '"' {
			inD = true
			f.pos++
			continue
		}
		if ch == ',' || ch == ']' || ch == '}' {
			break
		}
		if ch == ':' {
			// In flow seq context, "a:b" without space... ':' ends scalar only if followed by space/,/]/}?
			// For map keys we handle separately. Here: if followed by space or flow-end, stop (caller decides).
			if f.pos+1 >= len(f.s) || f.s[f.pos+1] == ' ' || f.s[f.pos+1] == '\t' || f.s[f.pos+1] == ',' || f.s[f.pos+1] == ']' || f.s[f.pos+1] == '}' {
				break
			}
		}
		if ch == '#' && (f.pos == 0 || f.s[f.pos-1] == ' ' || f.s[f.pos-1] == '\t') {
			break
		}
		f.pos++
	}
	text := strings.TrimSpace(f.s[start:f.pos])
	return &yNode{kind: yScalar, text: text, line: f.line}, nil
}

func (f *flowParser) parseQuoted() (*yNode, error) {
	q := f.s[f.pos]
	var sb strings.Builder
	i := f.pos + 1
	closed := false
	for i < len(f.s) {
		c := f.s[i]
		if q == '"' && c == '\\' {
			if i+1 >= len(f.s) {
				break
			}
			sb.WriteByte(c)
			sb.WriteByte(f.s[i+1])
			i += 2
			continue
		}
		if c == q {
			if q == '\'' && i+1 < len(f.s) && f.s[i+1] == '\'' {
				sb.WriteString("''")
				i += 2
				continue
			}
			closed = true
			i++
			break
		}
		sb.WriteByte(c)
		i++
	}
	if !closed {
		return nil, &yError{f.line, "found unexpected end of stream"}
	}
	raw := sb.String()
	var text string
	if q == '\'' {
		text = strings.ReplaceAll(raw, "''", "'")
	} else {
		text = unescapeDouble(raw, f.line)
	}
	f.pos = i
	return &yNode{kind: yScalar, text: text, quoted: true, line: f.line, closed: true, quoteChar: q}, nil
}

func (f *flowParser) parseSeq() (*yNode, error) {
	// consume '['
	f.pos++
	node := &yNode{kind: ySeq, line: f.line}
	f.skipSpaces()
	if f.pos < len(f.s) && f.s[f.pos] == ']' {
		f.pos++
		return node, nil
	}
	for {
		f.skipSpaces()
		if f.pos < len(f.s) && f.s[f.pos] == ']' {
			f.pos++
			return node, nil
		}
		if f.pos < len(f.s) && f.s[f.pos] == ',' {
			// empty item? "[, a]"? Actually leading comma means null item? yaml: [, a] -> [null, a]? Hmm.
			// Simplify: treat as null item.
			node.items = append(node.items, &yNode{kind: yScalar, line: f.line})
			f.pos++
			continue
		}
		if f.pos >= len(f.s) {
			return nil, &yError{f.line, "did not find expected ',' or ']'"}
		}
		// check for key: value (seq of maps? no - but "[a: b]"? That's... in flow seq, "a: b" is invalid? Actually YAML allows? No.
		// Just parse value; if followed by ':', it's an error in seq context? yaml.v2: "[a: b]" -> error? Hmm, actually single pair in seq is... let me allow map detection: if value followed by ':' then it's a map? No - keep simple: parse value, then expect , or ].
		nd, err := f.parseValue()
		if err != nil {
			return nil, err
		}
		f.skipSpaces()
		// ':' after value in seq? e.g. "[a: b]" - treat as error? yaml spec: flow seq can't contain mapping without {}? Actually "[a: b]" IS valid YAML meaning [{a: b}]? No... it's an error. Keep: if ':' follows, error.
		if f.pos < len(f.s) && f.s[f.pos] == ':' {
			return nil, &yError{f.line, "mapping values are not allowed in this context"}
		}
		node.items = append(node.items, nd)
		f.skipSpaces()
		if f.pos >= len(f.s) {
			return nil, &yError{f.line, "did not find expected ',' or ']'"}
		}
		if f.s[f.pos] == ',' {
			f.pos++
			// trailing comma "[a,]"? allowed -> continue (will hit ']' next)
			continue
		}
		if f.s[f.pos] == ']' {
			f.pos++
			return node, nil
		}
		return nil, &yError{f.line, "did not find expected ',' or ']'"}
	}
}

func (f *flowParser) parseMap() (*yNode, error) {
	f.pos++ // consume '{'
	node := &yNode{kind: yMap, line: f.line}
	f.skipSpaces()
	if f.pos < len(f.s) && f.s[f.pos] == '}' {
		f.pos++
		return node, nil
	}
	for {
		f.skipSpaces()
		if f.pos < len(f.s) && f.s[f.pos] == '}' {
			f.pos++
			return node, nil
		}
		if f.pos >= len(f.s) {
			return nil, &yError{f.line, "did not find expected ',' or '}'"}
		}
		// parse key
		var key *yNode
		if f.s[f.pos] == '"' || f.s[f.pos] == '\'' {
			qn, err := f.parseQuoted()
			if err != nil {
				return nil, err
			}
			key = qn
		} else {
			// plain key up to ':' 
			start := f.pos
			for f.pos < len(f.s) && f.s[f.pos] != ':' && f.s[f.pos] != ',' && f.s[f.pos] != '}' {
				f.pos++
			}
			kt := strings.TrimSpace(f.s[start:f.pos])
			// handle quoted inside? keep simple
			key = &yNode{kind: yScalar, text: kt, line: f.line}
		}
		f.skipSpaces()
		if f.pos >= len(f.s) || f.s[f.pos] != ':' {
			return nil, &yError{f.line, "did not find expected ',' or '}'"}
		}
		f.pos++ // consume ':'
		f.skipSpaces()
		var val *yNode
		if f.pos < len(f.s) && (f.s[f.pos] == ',' || f.s[f.pos] == '}') {
			val = &yNode{kind: yScalar, line: f.line}
		} else {
			v, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			val = v
		}
		node.keys = append(node.keys, key)
		node.vals = append(node.vals, val)
		f.skipSpaces()
		if f.pos >= len(f.s) {
			return nil, &yError{f.line, "did not find expected ',' or '}'"}
		}
		if f.s[f.pos] == ',' {
			f.pos++
			continue
		}
		if f.s[f.pos] == '}' {
			f.pos++
			return node, nil
		}
		return nil, &yError{f.line, "did not find expected ',' or '}'"}
	}
}

func isStdTag(tag string) bool {
	switch tag {
	case "!!str", "!!bool", "!!int", "!!float", "!!null", "!!seq", "!!map":
		return true
	}
	return false
}
