actions.command:
cat > yamldecode.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

// Scalar resolution mimicking yaml.v2 (with the quoted yes/no quirk).

func isNullText(s string) bool {
	switch s {
	case "", "null", "Null", "NULL", "~":
		return true
	}
	return false
}

func lowerIn(s string, set ...string) bool {
	l := strings.ToLower(s)
	for _, x := range set {
		if l == x {
			return true
		}
	}
	return false
}

// resolveTag returns the yaml tag for a scalar node: !!str, !!bool, !!int, !!float, or "" for null.
func resolveTag(nd *yNode) string {
	if nd.kind != yScalar {
		if nd.kind == ySeq {
			return "!!seq"
		}
		return "!!map"
	}
	// explicit standard tag overrides
	if nd.tag != "" {
		switch nd.tag {
		case "!!str":
			return "!!str"
		case "!!bool":
			return "!!bool"
		case "!!int":
			return "!!int"
		case "!!float":
			return "!!float"
		case "!!null":
			return ""
		}
	}
	t := nd.text
	// The yaml.v2 quirk: y/n/yes/no/on/off resolve to bool even when quoted.
	if lowerIn(t, "y", "yes", "n", "no", "on", "off") {
		return "!!bool"
	}
	if nd.quoted {
		return "!!str"
	}
	if isNullText(t) {
		return ""
	}
	if lowerIn(t, "true", "false") {
		return "!!bool"
	}
	if isYamlInt(t) {
		return "!!int"
	}
	if isYamlFloat(t) {
		return "!!float"
	}
	return "!!str"
}

func isYamlInt(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '-' || s[0] == '+' {
		i = 1
	}
	if i >= len(s) {
		return false
	}
	rest := s[i:]
	if strings.HasPrefix(rest, "0x") || strings.HasPrefix(rest, "0X") {
		h := rest[2:]
		if h == "" {
			return false
		}
		for _, c := range h {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') || c == '_') {
				return false
			}
		}
		return true
	}
	if strings.HasPrefix(rest, "0o") || strings.HasPrefix(rest, "0O") {
		o := rest[2:]
		if o == "" {
			return false
		}
		for _, c := range o {
			if !((c >= '0' && c <= '7') || c == '_') {
				return false
			}
		}
		return true
	}
	if strings.HasPrefix(rest, "0b") || strings.HasPrefix(rest, "0B") {
		b := rest[2:]
		if b == "" {
			return false
		}
		for _, c := range b {
			if !(c == '0' || c == '1' || c == '_') {
				return false
			}
		}
		return true
	}
	// decimal (allow underscores, commas? yaml allows 1,000? no - keep digits+_)
	for _, c := range rest {
		if !((c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	// underscores can't be leading/trailing? Simplify: accept.
	return true
}

func isYamlFloat(s string) bool {
	if s == "" {
		return false
	}
	l := strings.ToLower(s)
	if l == ".inf" || l == "+.inf" || l == "-.inf" || l == ".nan" {
		return true
	}
	// must contain . or e
	hasDot := strings.Contains(s, ".")
	hasE := strings.ContainsAny(strings.ToLower(s), "e")
	if !hasDot && !hasE {
		return false
	}
	i := 0
	if s[0] == '-' || s[0] == '+' {
		i = 1
	}
	rest := s[i:]
	if rest == "" {
		return false
	}
	// split mantissa/exponent
	eIdx := strings.IndexAny(strings.ToLower(rest), "e")
	mant := rest
	exp := ""
	if eIdx >= 0 {
		mant = rest[:eIdx]
		exp = rest[eIdx+1:]
		if exp != "" && (exp[0] == '+' || exp[0] == '-') {
			exp = exp[1:]
		}
		if exp == "" {
			return false
		}
		for _, c := range exp {
			if !(c >= '0' && c <= '9') {
				return false
			}
		}
	}
	if mant == "" || mant == "." {
		return false
	}
	dots := 0
	digits := 0
	for _, c := range mant {
		if c == '.' {
			dots++
			continue
		}
		if c >= '0' && c <= '9' {
			digits++
			continue
		}
		return false
	}
	if dots > 1 || digits == 0 {
		return false
	}
	if !hasDot && !hasE {
		return false
	}
	if !hasDot && hasE {
		// "1e3" - valid float
		return true
	}
	return true
}

func yamlBoolValue(nd *yNode) bool {
	t := strings.ToLower(nd.text)
	switch t {
	case "y", "yes", "true", "on":
		return true
	}
	return false
}

// decodeError is a single unmarshal error.
type decodeError struct {
	line int
	msg  string
}

type decoder struct {
	errs []decodeError
}

func (d *decoder) add(line int, msg string) {
	d.errs = append(d.errs, decodeError{line, msg})
}

func unmarshalErrLine(errs []decodeError) string {
	var sb strings.Builder
	sb.WriteString("yaml: unmarshal errors:")
	for _, e := range errs {
		sb.WriteString(fmt.Sprintf("\n  line %d: %s", e.line, e.msg))
	}
	return sb.String()
}

// scalar-to-string: null -> "", else literal text.
func (d *decoder) toString(nd *yNode, ctx string) (string, bool) {
	if nd.kind != yScalar {
		tag := resolveTag(nd)
		d.add(nd.line, fmt.Sprintf("cannot unmarshal %s into %s", tag, ctx))
		return "", false
	}
	tag := resolveTag(nd)
	if tag == "" {
		return "", true
	}
	return nd.text, true
}

func (d *decoder) toBool(nd *yNode) (bool, bool) {
	if nd.kind != yScalar {
		tag := resolveTag(nd)
		d.add(nd.line, fmt.Sprintf("cannot unmarshal %s into bool", tag))
		return false, false
	}
	tag := resolveTag(nd)
	if tag == "" {
		return false, true
	}
	if tag == "!!bool" {
		return yamlBoolValue(nd), true
	}
	if tag == "!!str" {
		d.add(nd.line, fmt.Sprintf("cannot unmarshal !!str `%s` into bool", nd.text))
		return false, false
	}
	if tag == "!!int" {
		d.add(nd.line, fmt.Sprintf("cannot unmarshal !!int `%s` into bool", nd.text))
		return false, false
	}
	d.add(nd.line, fmt.Sprintf("cannot unmarshal !!float `%s` into bool", nd.text))
	return false, false
}

// mapEntries returns merged entries: explicit keys in order (with dup detection),
// merged (<<) keys filled in. Each entry: key string, value node, key line.
type mapEntry struct {
	key  string
	val  *yNode
	line int
}

func (d *decoder) mapEntries(nd *yNode) []mapEntry {
	var out []mapEntry
	seen := map[string]bool{}
	var merges []*yNode // merge sources in order
	for i := range nd.keys {
		k := nd.keys[i].text
		v := nd.vals[i]
		if k == "<<" {
			merges = append(merges, v)
			continue
		}
		if seen[k] {
			// find first line
			first := 0
			for _, e := range out {
				if e.key == k {
					first = e.line
					break
				}
			}
			d.add(nd.keys[i].line, fmt.Sprintf("mapping key %q already defined at line %d", k, first))
			continue
		}
		seen[k] = true
		out = append(out, mapEntry{k, v, nd.keys[i].line})
	}
	// apply merges (explicit wins; earlier merge wins)
	for _, m := range merges {
		var sources []*yNode
		if m.kind == ySeq {
			sources = m.items
		} else {
			sources = []*yNode{m}
		}
		for _, s := range sources {
			if s.kind != yMap {
				continue
			}
			sub := d.mapEntries(s)
			for _, e := range sub {
				if !seen[e.key] {
					seen[e.key] = true
					out = append(out, e)
				}
			}
		}
	}
	return out
}

// Config structures.
type cheatpathCfg struct {
	name     string
	path     string
	tags     []string
	readonly bool
	hasPath  bool
}

type configFile struct {
	editor    string
	colorize  bool
	style     string
	formatter string
	pager     string
	paths     []cheatpathCfg
}

func decodeConfig(root *yNode) (*configFile, []decodeError) {
	d := &decoder{}
	cfg := &configFile{}
	if root == nil {
		return cfg, nil
	}
	if root.kind != yMap {
		tag := resolveTag(root)
		if root.kind == yScalar {
			d.add(root.line, fmt.Sprintf("cannot unmarshal %s `%s` into config.Config", tag, root.text))
		} else {
			d.add(root.line, fmt.Sprintf("cannot unmarshal %s into config.Config", tag))
		}
		return cfg, d.errs
	}
	for _, e := range d.mapEntries(root) {
		switch e.key {
		case "editor":
			if s, ok := d.toString(e.val, "string"); ok {
				cfg.editor = s
			}
		case "colorize":
			if b, ok := d.toBool(e.val); ok {
				cfg.colorize = b
			}
		case "style":
			if s, ok := d.toString(e.val, "string"); ok {
				cfg.style = s
			}
		case "formatter":
			if s, ok := d.toString(e.val, "string"); ok {
				cfg.formatter = s
			}
		case "pager":
			if s, ok := d.toString(e.val, "string"); ok {
				cfg.pager = s
			}
		case "cheatpaths":
			cfg.paths = d.decodePaths(e.val)
		default:
			// unknown fields ignored
		}
	}
	return cfg, d.errs
}

func (d *decoder) decodePaths(nd *yNode) []cheatpathCfg {
	if nd.kind == yScalar && resolveTag(nd) == "" {
		return nil
	}
	if nd.kind != ySeq {
		tag := resolveTag(nd)
		if nd.kind == yScalar {
			d.add(nd.line, fmt.Sprintf("cannot unmarshal %s `%s` into []cheatpath.Path", tag, nd.text))
		} else {
			d.add(nd.line, fmt.Sprintf("cannot unmarshal %s into []cheatpath.Path", tag))
		}
		return nil
	}
	var out []cheatpathCfg
	for _, it := range nd.items {
		if it.kind == yScalar && resolveTag(it) == "" {
			continue // null items skipped
		}
		if it.kind != yMap {
			tag := resolveTag(it)
			if it.kind == yScalar {
				d.add(it.line, fmt.Sprintf("cannot unmarshal %s `%s` into cheatpath.Path", tag, it.text))
			} else {
				d.add(it.line, fmt.Sprintf("cannot unmarshal %s into cheatpath.Path", tag))
			}
			continue
		}
		var cp cheatpathCfg
		for _, e := range d.mapEntries(it) {
			switch e.key {
			case "name":
				if s, ok := d.toString(e.val, "string"); ok {
					cp.name = s
				}
			case "path":
				if s, ok := d.toString(e.val, "string"); ok {
					cp.path = s
					cp.hasPath = true
				}
			case "tags":
				cp.tags = d.decodeTags(e.val)
			case "readonly":
				if b, ok := d.toBool(e.val); ok {
					cp.readonly = b
				}
			default:
			}
		}
		out = append(out, cp)
	}
	return out
}

func (d *decoder) decodeTags(nd *yNode) []string {
	if nd.kind == yScalar && resolveTag(nd) == "" {
		return nil
	}
	if nd.kind != ySeq {
		tag := resolveTag(nd)
		if nd.kind == yScalar {
			d.add(nd.line, fmt.Sprintf("cannot unmarshal %s `%s` into []string", tag, nd.text))
		} else {
			d.add(nd.line, fmt.Sprintf("cannot unmarshal %s into []string", tag))
		}
		return nil
	}
	var out []string
	for _, it := range nd.items {
		if it.kind == yScalar && resolveTag(it) == "" {
			continue
		}
		if s, ok := d.toString(it, "string"); ok {
			out = append(out, s)
		}
	}
	return out
}

// Frontmatter.
type frontmatter struct {
	syntax string
	tags   []string
}

func decodeFrontmatter(root *yNode) (*frontmatter, []decodeError) {
	d := &decoder{}
	fm := &frontmatter{}
	if root == nil {
		return fm, nil
