package main

import (
	"fmt"
	"os"
	"os/user"
	"path/filepath"
	"strings"
)

type cfgStatus int

const (
	cfgOK cfgStatus = iota
	cfgDeclined
	cfgInstalled
	cfgError
)

// loadedConfig is the validated runtime config.
type loadedConfig struct {
	editor    string // resolved: VISUAL > EDITOR > config (first raw non-empty; config trimmed at load)
	colorize  bool
	style     string
	formatter string // "" means default (terminal)
	pager     string
	paths     []runtimePath
	confPath  string
}

type runtimePath struct {
	name     string
	path     string // cleaned + resolved
	tags     []string
	readonly bool
}

func homeDir() string {
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	if u, err := user.Current(); err == nil {
		return u.HomeDir
	}
	return ""
}

func expandTilde(p string) string {
	if p == "~" {
		return homeDir()
	}
	if strings.HasPrefix(p, "~/") {
		return homeDir() + p[1:]
	}
	return p
}

// findConfigPath locates the config file. Returns path or "" if none.
func findConfigPath() string {
	if v, ok := os.LookupEnv("CHEAT_CONFIG_PATH"); ok && v != "" {
		p := expandTilde(v)
		if fileExists(p) {
			return p
		}
		return ""
	}
	// If CHEAT_CONFIG_PATH is set (even empty?) - hmm: set-but-empty?
	// Observed: only non-empty honored? Actually if set to ""... treat as unset? Test later.
	// For now: set+non-empty claims the slot (missing -> not found).
	if v, ok := os.LookupEnv("CHEAT_CONFIG_PATH"); ok && v == "" {
		// fall through to other paths? Uncertain; treat as unset.
		_ = v
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		p := filepath.Join(xdg, "cheat", "conf.yml")
		if fileExists(p) {
			return p
		}
	}
	hd := homeDir()
	if hd != "" {
		p := filepath.Join(hd, ".config", "cheat", "conf.yml")
		if fileExists(p) {
			return p
		}
		p2 := filepath.Join(hd, ".cheat", "conf.yml")
		if fileExists(p2) {
			return p2
		}
	}
	if fileExists("/etc/cheat/conf.yml") {
		return "/etc/cheat/conf.yml"
	}
	return ""
}

func fileExists(p string) bool {
	fi, err := os.Stat(p)
	if err != nil {
		return false
	}
	return !fi.IsDir()
}

func loadConfigOrInstall() (*loadedConfig, string, cfgStatus) {
	path := findConfigPath()
	if path == "" {
		return runInstaller()
	}
	cfg, errStr := loadConfigFile(path)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return nil, "", cfgError
	}
	return cfg, path, cfgOK
}

func loadConfigFile(path string) (*loadedConfig, string) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Sprintf("failed to load config: could not read config file: %v", err)
	}
	root, err := parseYAMLDoc(string(data))
	if err != nil {
		return nil, fmt.Sprintf("failed to load config: could not unmarshal yaml: %v", err)
	}
	cf, derrs := decodeConfig(root)
	if len(derrs) > 0 {
		return nil, fmt.Sprintf("failed to load config: could not unmarshal yaml: %s", unmarshalErrLine(derrs))
	}
	return validateConfig(cf, path)
}

func validateConfig(cf *configFile, confPath string) (*loadedConfig, string) {
	lc := &loadedConfig{confPath: confPath}
	// editor: config trimmed; resolution first raw non-empty of VISUAL, EDITOR, trimmed-config
	cfgEd := strings.TrimSpace(cf.editor)
	vis := os.Getenv("VISUAL")
	ed := os.Getenv("EDITOR")
	resolved := ""
	if vis != "" {
		resolved = vis
	} else if ed != "" {
		resolved = ed
	} else {
		resolved = cfgEd
	}
	if resolved == "" {
		return nil, "failed to load config: no editor set"
	}
	lc.editor = resolved
	lc.colorize = cf.colorize
	lc.style = cf.style
	lc.formatter = cf.formatter
	lc.pager = cf.pager

	// cheatpaths: expand ~, check existence (warn+skip), clean+resolve, add cwd, zero-check, names, formatter.
	type tmpPath struct {
		name     string
		path     string
		tags     []string
		readonly bool
	}
	var kept []tmpPath
	for _, cp := range cf.paths {
		ep := expandTilde(cp.path)
		if !pathExists(ep) {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", ep)
			continue
		}
		final := resolveCheatpath(ep)
		kept = append(kept, tmpPath{cp.name, final, cp.tags, cp.readonly})
	}
	// cwd cheatpath
	cwd, err := os.Getwd()
	if err != nil {
		return nil, fmt.Sprintf("failed to load config: failed to get cwd: %v", err)
	}
	if dotcheat := findDotCheat(cwd); dotcheat != "" {
		kept = append(kept, tmpPath{"cwd", resolveCheatpath(dotcheat), nil, false})
	}
	if len(kept) == 0 {
		return nil, "failed to load config: config error: no cheatpaths specified"
	}
	seen := map[string]bool{}
	for _, k := range kept {
		if k.name == "" {
			return nil, "failed to load config: config error: cheatpath name cannot be empty"
		}
		if seen[k.name] {
			return nil, fmt.Sprintf("failed to load config: config error: cheatpath name is not unique: %s", k.name)
		}
		seen[k.name] = true
	}
	if lc.formatter != "" && lc.formatter != "terminal" && lc.formatter != "terminal256" && lc.formatter != "terminal16m" {
		return nil, fmt.Sprintf("failed to load config: config error: formatter is invalid: %s", lc.formatter)
	}
	for _, k := range kept {
		lc.paths = append(lc.paths, runtimePath{k.name, k.path, k.tags, k.readonly})
	}
	return lc, ""
}

func pathExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

// resolveCheatpath cleans and resolves symlinks per observed rules:
// cleaned = Clean(expanded); if EvalSymlinks differs from Abs(cleaned), use resolved.
func resolveCheatpath(p string) string {
	cleaned := filepath.Clean(p)
	resolved, err := filepath.EvalSymlinks(cleaned)
	if err != nil {
		return cleaned
	}
	abs, err := filepath.Abs(cleaned)
	if err != nil {
		return cleaned
	}
	abs = filepath.Clean(abs)
	if resolved != abs {
		return resolved
	}
	return cleaned
}

func findDotCheat(cwd string) string {
	dir := cwd
	for {
		cand := filepath.Join(dir, ".cheat")
		if fi, err := os.Stat(cand); err == nil && fi.IsDir() {
			return cand
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}
