	if err := os.WriteFile(confPath, []byte(content), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "failed to run installer: %v\n", err)
		return nil, "", cfgError
	}
	fmt.Fprintf(os.Stdout, "Created config file: %s\n", confPath)
	fmt.Fprintln(os.Stdout, "Please read this file for advanced configuration information.")
	return nil, "", cfgInstalled
}

func cloneCommunity(dir string) error {
	// Best effort replication of `git clone https://github.com/cheat/cheatsheets.git <dir>`.
	// Offline this always fails; wrap error to resemble observed format.
	cmd := exec.Command("git", "clone", "https://github.com/cheat/cheatsheets.git", dir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		msg := strings.TrimSpace(string(out))
		if msg == "" {
			msg = err.Error()
		} else {
			// git prints errors to stderr; use first line? Observed go-git format differs anyway.
			lines := strings.Split(msg, "\n")
			msg = lines[0]
		}
		return fmt.Errorf("failed to clone cheatsheets: %s", msg)
	}
	return nil
}
