	pathIdx  int // index of cheatpath in config (for precedence/sort stability)
}

// loadSheets walks all cheatpaths and loads sheets. On error returns message.
func loadSheets(cfg *loadedConfig) ([]sheet, string) {
	var all []sheet
	for idx, rp := range cfg.paths {
		sh, errStr := loadCheatpath(rp, idx)
		if errStr != "" {
			return nil, errStr
		}
		all = append(all, sh...)
	}
	// sort by title, stable by pathIdx (config order)
	sort.SliceStable(all, func(i, j int) bool {
		if all[i].title != all[j].title {
			return all[i].title < all[j].title
		}
		return all[i].pathIdx < all[j].pathIdx
	})
	return all, ""
}

func loadCheatpath(rp runtimePath, idx int) ([]sheet, string) {
	var out []sheet
	fi, err := os.Stat(rp.path)
	if err != nil {
		// shouldn't happen (checked at load), but handle
		return nil, fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to walk path: %v", err)
	}
	if !fi.IsDir() {
		// file cheatpath: single sheet with empty title
		return loadFileSheet(rp, idx, rp.path, "")
	}
	walkErr := ""
	filepath.WalkDir(rp.path, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			walkErr = fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to walk path: %v", err)
			return filepath.SkipAll
		}
		if p == rp.path {
			return nil
		}
		// lstat already (WalkDir doesn't follow); dirs traversed, others are candidates
		if d.IsDir() {
			return nil
		}
		base := filepath.Base(p)
		if strings.HasPrefix(base, ".") {
			return nil
		}
		if filepath.Ext(base) != "" {
			return nil
		}
		rel, err := filepath.Rel(rp.path, p)
		if err != nil {
			return nil
		}
		title := filepath.ToSlash(rel)
		sh, errStr := loadFileSheet(rp, idx, p, title)
		if errStr != "" {
			walkErr = errStr
			return filepath.SkipAll
		}
		out = append(out, sh...)
		return nil
	})
	if walkErr != "" {
		return nil, walkErr
	}
	return out, ""
}

func loadFileSheet(rp runtimePath, idx int, file, title string) ([]sheet, string) {
	data, err := os.ReadFile(file)
	if err != nil {
		return nil, fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to load sheet: %s, path: %s, err: failed to read file: %s, %v", title, file, file, err)
	}
	content := string(data)
	var fm *frontmatter
	body, fmText, hasFM, delimErr := splitFrontmatter(content)
	if delimErr {
		return nil, fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to load sheet: %s, path: %s, err: failed to parse front-matter: failed to delimit frontmatter", title, file)
	}
	if hasFM {
		root, err := parseYAMLDoc(fmText)
		if err != nil {
			return nil, fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to load sheet: %s, path: %s, err: failed to parse front-matter: failed to unmarshal frontmatter: %v", title, file, err)
		}
		dec, derrs := decodeFrontmatter(root)
		if len(derrs) > 0 {
			return nil, fmt.Sprintf("failed to list cheatsheets: failed to load cheatsheets: failed to load sheet: %s, path: %s, err: failed to parse front-matter: failed to unmarshal frontmatter: %s", title, file, unmarshalErrLine(derrs))
		}
		fm = dec
	} else {
		fm = &frontmatter{}
	}
	tags := append([]string{}, rp.tags...)
	tags = append(tags, fm.tags...)
	sort.Strings(tags)
	return []sheet{{
		title:    title,
		path:     file,
		cheat:    rp.name,
		tags:     tags,
		syntax:   fm.syntax,
		content:  body,
		readonly: rp.readonly,
		pathIdx:  idx,
	}}, ""
}

// splitFrontmatter splits content into body, frontmatter text, hasFM, delimError.
func splitFrontmatter(content string) (body, fmText string, hasFM, delimErr bool) {
	var newline string
	var rest string
	if strings.HasPrefix(content, "---\r\n") {
		newline = "\r\n"
		rest = content[5:]
	} else if strings.HasPrefix(content, "---\n") {
		newline = "\n"
		rest = content[4:]
	} else {
		return content, "", false, false
	}
	if newline == "\n" {
		lines := strings.Split(rest, "\n")
		// scan for exact "---"; any \r in scanned region -> silent no-fm
		for i, ln := range lines {
			if strings.Contains(ln, "\r") {
				return content, "", false, false
			}
			if ln == "---" {
				fm := strings.Join(lines[:i], "\n")
				body := strings.Join(lines[i+1:], "\n")
				return body, fm, true, false
			}
		}
		return "", "", false, true
	}
	// CRLF mode
	lines := strings.Split(rest, "\r\n")
	for i, ln := range lines {
		if ln == "---" {
			fm := strings.Join(lines[:i], "\r\n")
			body := strings.Join(lines[i+1:], "\r\n")
			return body, fm, true, false
		}
	}
	return "", "", false, true
}

// filterSheets applies path/tag filters.
func filterSheets(all []sheet, p *parsedArgs, cfg *loadedConfig) ([]sheet, string) {
	// path validation (if flag changed)
	if p.changed["path"] {
		name := p.strings["path"]
		found := false
		for _, rp := range cfg.paths {
			if rp.name == name {
				found = true
				break
			}
		}
		if !found {
			return nil, fmt.Sprintf("invalid option --path: cheatpath does not exist: %s", name)
		}
	}
	var out []sheet
	for _, s := range all {
		if p.changed["path"] && s.cheat != p.strings["path"] {
			continue
		}
		if p.changed["tag"] {
			want := p.strings["tag"]
			hit := false
			for _, t := range s.tags {
				if t == want {
					hit = true
					break
				}
			}
			if !hit {
				continue
			}
		}
		out = append(out, s)
	}
	return out, ""
}

// findSheet finds the most-local sheet with exact title among filtered.
func findSheet(all []sheet, title string) *sheet {
	var best *sheet
	for i := range all {
		if all[i].title == title {
			if best == nil || all[i].pathIdx > best.pathIdx {
				best = &all[i]
			}
		}
	}
	return best
}

// findSheetsAll finds all sheets with exact title (in path order).
func findSheetsAll(all []sheet, title string) []sheet {
	var out []sheet
	for _, s := range all {
		if s.title == title {
			out = append(out, s)
		}
	}
	// sort by pathIdx (config order)
	sort.SliceStable(out, func(i, j int) bool { return out[i].pathIdx < out[j].pathIdx })
	return out
}
