{"command":"cat > actions.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strings"
)

func dispatch(cfg *loadedConfig, cfgPath string, p *parsedArgs) int {
	if p.bools["conf"] {
		fmt.Fprintln(os.Stdout, cfgPath)
		return 0
	}
	if p.bools["directories"] {
		return cmdDirs(cfg, p)
	}
	if p.changed["edit"] {
		return cmdEdit(cfg, p)
	}
	if p.bools["list"] || p.bools["brief"] {
		return cmdList(cfg, p)
	}
	if p.bools["tags"] {
		return cmdTags(cfg, p)
	}
	if p.bools["update"] {
		return cmdUpdate(cfg, p)
	}
	if p.changed["search"] {
		return cmdSearch(cfg, p)
	}
	if p.changed["rm"] {
		return cmdRemove(cfg, p)
	}
	// view / tag-implied list / help
	if len(p.positionals) == 1 {
		return cmdView(cfg, p, p.positionals[0])
	}
	if p.changed["tag"] && p.strings["tag"] != "" {
		return cmdList(cfg, p)
	}
	fmt.Fprint(os.Stdout, helpText)
	return 0
}

// isTerminal reports whether stdout is a terminal.
func isTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func shouldColorize(cfg *loadedConfig, p *parsedArgs) bool {
	if p.bools["colorize"] {
		return true
	}
	return cfg.colorize && isTerminal()
}

// writePager writes s through the configured pager (or stdout if none).
// Returns error string or "".
func writePager(cfg *loadedConfig, s string) string {
	fields := strings.Fields(cfg.pager)
	if len(fields) == 0 {
		fmt.Fprint(os.Stdout, s)
		return ""
	}
	cmd := exec.Command(fields[0], fields[1:]...)
	cmd.Stdin = strings.NewReader(s)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		// Map errors like Go's exec: LookPath errors vs exit errors.
		if ee, ok := err.(*exec.Error); ok {
			_ = ee
			return fmt.Sprintf("failed to write to pager: %v", err)
		}
		return fmt.Sprintf("failed to write to pager: %v", err)
	}
	return ""
}

// ---- view ----

func cmdView(cfg *loadedConfig, p *parsedArgs, title string) int {
	all, errStr := loadSheets(cfg)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return 1
	}
	filtered, errStr := filterSheets(all, p, cfg)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return 1
	}
	if p.bools["all"] {
		matches := findSheetsAll(filtered, title)
		var sb strings.Builder
		for i, s := range matches {
			if i > 0 {
				sb.WriteString("\n")
			}
			sb.WriteString(formatSearchSheet(cfg, p, s))
			sb.WriteString("\n")
		}
		if es := writePager(cfg, sb.String()); es != "" {
			fmt.Fprintln(os.Stderr, es)
			return 1
		}
		return 0
	}
	best := findSheet(filtered, title)
	if best == nil {
		fmt.Fprintf(os.Stdout, "No cheatsheet found for '%s'.\n", title)
		return 2
	}
	out := best.content
	if shouldColorize(cfg, p) {
		out = highlightContent(best.content, best.syntax, cfg)
	}
	if es := writePager(cfg, out); es != "" {
		fmt.Fprintln(os.Stderr, es)
		return 1
	}
	return 0
}

// ---- list/brief ----

func cmdList(cfg *loadedConfig, p *parsedArgs) int {
	all, errStr := loadSheets(cfg)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return 1
	}
	filtered, errStr := filterSheets(all, p, cfg)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return 1
	}
	// positional filter (case-insensitive regex on title)
	if len(p.positionals) == 1 {
		pat := "(?i)" + p.positionals[0]
		re, err := regexp.Compile(pat)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to compile regexp: %s, %v\n", p.positionals[0], err)
			// NOTE: message check needed: observed "failed to compile regexp: (?i)(unclosed, error parsing regexp: ...".
			// So it prints the FULL pattern with (?i) prefix.
			return 1
		}
		var kept []sheet
		for _, s := range filtered {
			if re.MatchString(s.title) {
				kept = append(kept, s)
			}
		}
		filtered = kept
	}
	if len(filtered) == 0 {
		return 2
	}
	var sb strings.Builder
	if p.bools["brief"] {
		writeBriefTable(&sb, filtered)
	} else {
		writeListTable(&sb, filtered)
	}
	if es := writePager(cfg, sb.String()); es != "" {
		fmt.Fprintln(os.Stderr, es)
		return 1
	}
	return 0
}

func writeListTable(sb *strings.Builder, sheets []sheet) {
	w0, w1 := len("title:"), len("file:")
	for _, s := range sheets {
		if len(s.title) > w0 {
			w0 = len(s.title)
		}
		if len(s.path) > w1 {
			w1 = len(s.path)
		}
	}
	w0++
	w1++
	sb.WriteString(padRight("title:", w0))
	sb.WriteString(padRight("file:", w1))
	sb.WriteString("tags:\n")
	for _, s := range sheets {
		sb.WriteString(padRight(s.title, w0))
		sb.WriteString(padRight(s.path, w1))
		sb.WriteString(strings.Join(s.tags, ","))
		sb.WriteString("\n")
	}
}

func writeBriefTable(sb *strings.Builder, sheets []sheet) {
	w0 := len("title:")
	for _, s := range sheets {
		if len(s.title) > w0 {
			w0 = len(s.title)
		}
	}
	w0++
	sb.WriteString(padRight("title:", w0))
	sb.WriteString("tags:\n")
	for _, s := range sheets {
		sb.WriteString(padRight(s.title, w0))
		sb.WriteString(strings.Join(s.tags, ","))
		sb.WriteString("\n")
	}
}

func padRight(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

// ---- tags ----

func cmdTags(cfg *loadedConfig, p *parsedArgs) int {
	all, errStr := loadSheets(cfg)
	if errStr != "" {
		fmt.Fprintln(os.Stderr, errStr)
		return 1
	}
	// -T respects -p (filter) but ignores -t. Use filterSheets but without tag.
	// filterSheets validates -p and applies both; -t is ignored for -T.
	// Implement manually: validate path, filter by path only.
	if p.changed["path"] {
		name := p.strings["path"]
		found := false
		for _, rp := range cfg.paths {
			if rp.name == name {
				found = true
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "invalid option --path: cheatpath does not exist: %s\n", name)
			return 1
		}
	}
	seen := map[string]bool{}
	var tags []string
	for _, s := range all {
		if p.changed["path"] && s.cheat != p.strings["path"] {
			continue
		}
		for _, t := range s.tags {
			if !seen[t] {
				seen[t] = true
				tags = append(tags, t)
			}
		}
	}
	sort.Strings(tags)
	var sb strings.Builder
	for _, t := range tags {
		sb.WriteString(t)
		sb.WriteString("\n")
	}
	if es := writePager(cfg, sb.String()); es != "" {
		fmt.Fprintln(os.Stderr, es)
		return 1
	}
	return 0
}

// ---- dirs ----

func cmdDirs(cfg *loadedConfig, p *parsedArgs) int {
	// -d respects -p (validate + filter), ignores -t.
	if p.changed["path"] {
		name := p.strings["path"]
		found := false
		for _, rp := range cfg.paths {
			if rp.name == name {
				found = true
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "invalid option --path: cheatpath does not exist: %s\n", name)
			return 1
		}
	}
	type entry struct{ name, path string }
	var list []entry
	w := 0
	for _, rp := range cfg.paths {
		if p.changed["path"] && rp.name != p.strings["path"] {
			continue
		}
		n := rp.name + ":"
		if len(n) > w {
			w = len(n)
