// updateOne updates a single cheatpath. Returns (message, isError).
func updateOne(path string) (string, bool) {
	fi, err := os.Stat(path)
	if err != nil || !fi.IsDir() {
		// replicate go-git open error: stat <path>/.git: ...
		_, serr := os.Stat(path + "/.git")
		if serr != nil {
			return fmt.Sprintf("error (%v)", serr), true
		}
		return "error (not a git repository)", true
	}
	// valid repo?
	if !isGitRepo(path) {
		return "skipped (not a git repository)", false
	}
	// bare?
	if isBareRepo(path) {
		return "error (worktree not available in a bare repository)", true
	}
	// dirty?
	dirty, derr := isDirtyWorktree(path)
	if derr != "" {
		return derr, true
	}
	if dirty {
		return "skipped (dirty worktree)", false
	}
	// origin remote?
	originURL, ok := gitRemoteURL(path)
	if !ok {
		return "error (remote not found)", true
	}
	// fetch
	if ferr := gitFetch(path); ferr != "" {
		// file-as-remote?
		if isLocalFile(originURL, path) {
			return fmt.Sprintf("error (unknown error: fatal: invalid gitfile format: %s)", originURL), true
		}
		return "error (repository not found)", true
	}
	// upstream? if none (untracked/detached), ok
	upstream, hasUp := gitUpstream(path)
	if !hasUp || upstream == "" {
		return "ok", false
	}
	// ff-only merge
	if merr := gitMergeFF(path, upstream); merr != "" {
		return merr, true
	}
	return "ok", false
}

func gitCmd(path string, args ...string) (string, string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = path
	var outBuf, errBuf strings.Builder
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	// avoid prompts and advice noise
	cmd.Env = append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0",
		"GIT_EDITOR=true",
		"GIT_MERGE_AUTOEDIT=no",
		"LANG=C",
		"LC_ALL=C",
	)
	err := cmd.Run()
	return outBuf.String(), errBuf.String(), err
}

func isGitRepo(path string) bool {
	_, _, err := gitCmd(path, "rev-parse", "--git-dir")
	return err == nil
}

func isBareRepo(path string) bool {
	out, _, err := gitCmd(path, "rev-parse", "--is-bare-repository")
	if err != nil {
		return false
	}
	return strings.TrimSpace(out) == "true"
}

func isDirtyWorktree(path string) (bool, string) {
	out, _, err := gitCmd(path, "status", "--porcelain")
	if err != nil {
		// corrupted? check HEAD resolvability
		_, _, herr := gitCmd(path, "rev-parse", "--verify", "HEAD")
		if herr != nil {
			return false, "error (object not found)"
		}
		// unknown status failure; wrap first line?
		return false, "error (object not found)"
	}
	return strings.TrimSpace(out) != "", ""
}

func gitRemoteURL(path string) (string, bool) {
	out, _, err := gitCmd(path, "remote", "get-url", "origin")
	if err != nil {
		return "", false
	}
	// get-url may print multiple lines (fetch/push)? take first
	lines := strings.Split(strings.TrimSpace(out), "\n")
	if len(lines) == 0 || lines[0] == "" {
		return "", false
	}
	return strings.TrimSpace(lines[0]), true
}

func gitFetch(path string) string {
	_, _, err := gitCmd(path, "fetch", "origin")
	if err != nil {
		return "fetch failed"
	}
	return ""
}

func isLocalFile(url, repoPath string) bool {
	u := url
	if strings.HasPrefix(u, "file://") {
		u = strings.TrimPrefix(u, "file://")
		// file://host/path? strip host
		if strings.HasPrefix(u, "/") {
			// absolute, keep
		} else if idx := strings.IndexByte(u, '/'); idx >= 0 {
			u = u[idx:]
		}
	} else {
		// scp-like (host:path), scheme (http://), etc. are not local files
		if strings.Contains(u, "://") {
			return false
		}
		if at := strings.IndexByte(u, '@'); at >= 0 && strings.IndexByte(u, ':') > at {
			return false
		}
		if !strings.HasPrefix(u, "/") && !strings.HasPrefix(u, "./") && !strings.HasPrefix(u, "../") {
			// could be scp-like "host:path" or plain local path
			if idx := strings.IndexByte(u, ':'); idx >= 0 {
				return false
			}
		}
	}
	if !strings.HasPrefix(u, "/") {
		u = repoPath + "/" + u
	}
	fi, err := os.Stat(u)
	if err != nil {
		return false
	}
	return !fi.IsDir()
}

func gitUpstream(path string) (string, bool) {
	out, _, err := gitCmd(path, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
	if err != nil {
		return "", false
	}
	u := strings.TrimSpace(out)
	if u == "" {
		return "", false
	}
	return u, true
}

func gitMergeFF(path, upstream string) string {
	_, stderr, err := gitCmd(path, "merge", "--ff-only", upstream)
	if err != nil {
		if strings.Contains(stderr, "Not possible to fast-forward") {
			return "error (non-fast-forward update)"
		}
		// already up to date is success (exit 0). Other failures:
		if strings.Contains(stderr, "not something we can merge") {
			return "error (object not found)"
		}
		// fallback: map to non-fast-forward? or repository not found? Use generic.
		first := strings.TrimSpace(stderr)
		if idx := strings.IndexByte(first, '\n'); idx >= 0 {
			first = first[:idx]
		}
		if first == "" {
			first = "merge failed"
		}
		return fmt.Sprintf("error (unknown error: %s)", first)
	}
	return ""
}
