}

func resolveLexer(syntax string) string {
	s := strings.ToLower(strings.TrimSpace(syntax))
	if s == "" {
		return "bash"
	}
	switch s {
	case "bash", "sh", "shell", "zsh":
		return "bash"
	case "fish":
