	// Observed missing-formatter(empty->terminal) with monokai -> terminal colors (that's monokai+terminal).
	// For empty style + terminal256:
	if formatter == "terminal256" || formatter == "terminal16m" {
		if typ == "Comment" {
			return "\x1b[3m"
		}
		return ""
	}
