	if typ == "Comment" {
		return "\x1b[3m"
	}
	return ""
}

func fallbackColor(typ, formatter string) string {
	// Invalid style name: observed terminal256 comment=6, text=254.
	if formatter == "terminal256" {
		switch typ {
		case "Comment":
			return "\x1b[38;5;6m"
		case "String":
			return "\x1b[38;5;186m" // guess
		case "Number":
			return "\x1b[38;5;141m" // guess
