		case "Error":
			return "\x1b[38;5;89m\x1b[48;5;232m" // guess
		default:
			return "\x1b[38;5;254m"
		}
	}
	return ""
}

func emitToken(sb *strings.Builder, t token, style, formatter string) {
	text := t.text
	if text == "" {
		// Even empty tokens emit color+reset? Observed trailing empty 231 tokens.
		// But only when...? The trailing empty appears when last token of line isn't Text.
		// Our lexer must generate these; here just emit.
		if col := styleColor(style, t.typ, formatter); col != "" {
			sb.WriteString(col)
			sb.WriteString("\x1b[0m")
		}
		return
	}
	// Split on newlines: newlines emitted raw.
	parts := strings.Split(text, "\n")
	col := styleColor(style, t.typ, formatter)
	for i, pt := range parts {
		if i > 0 {
			sb.WriteString("\n")
		}
		if pt == "" {
			continue
		}
		if col != "" {
			sb.WriteString(col)
			sb.WriteString(pt)
			sb.WriteString("\x1b[0m")
		} else {
			sb.WriteString(pt)
		}
	}
}
EOF
