	"trap": true, "wait": true, "history": true, "type": true, "let": true,
	"dirs": true, "pushd": true, "popd": true, "caller": true,
	"complete": true, "hash": true, "help": true, "bind": true,
	"suspend": true, "disown": true, "enable": true, "shopt": true,
	"logout": true, "getopts": true, "time": true, "fc": true,
	"compgen": true, "ulimit": true, "times": true,
}

func lexTokens(lex, content string) []token {
	switch lex {
	case "bash":
		return lexBash(content)
	case "text":
		return lexText(content)
	case "python":
		return lexPython(content)
	case "javascript":
		return lexJavascript(content)
	case "fish":
		return lexFish(content)
	default:
		if isGenericLang(lex) {
			return lexGeneric(content, lex)
		}
		return lexText(content)
	}
}

func isGenericLang(lex string) bool {
	switch lex {
	case "go", "ruby", "java", "c", "cpp", "rust", "php", "perl",
		"yaml", "json", "markdown", "html", "css", "sql", "dockerfile",
		"ini", "toml", "console", "shellsession":
		return true
	}
	return false
}

// lexText: each line is a single Text token (with trailing \n attached if present).
func lexText(content string) []token {
	if content == "" {
		return nil
	}
	var toks []token
	// split keeping newlines
	start := 0
	for start < len(content) {
		idx := strings.IndexByte(content[start:], '\n')
		if idx < 0 {
			toks = append(toks, token{"Text", content[start:]})
			break
		}
		toks = append(toks, token{"Text", content[start : start+idx+1]})
		start = start + idx + 1
	}
	return toks
}

// --- Bash lexer ---

type bashCtx struct {
	s      string
	pos    int
	toks   []token
	textSB strings.Builder // current Text run
}

func (b *bashCtx) flushText() {
	if b.textSB.Len() > 0 {
		b.toks = append(b.toks, token{"Text", b.textSB.String()})
		b.textSB.Reset()
	}
}

func (b *bashCtx) addText(s string) {
	b.textSB.WriteString(s)
}

func (b *bashCtx) addTok(typ, s string) {
	b.flushText()
	if s != "" {
		b.toks = append(b.toks, token{typ, s})
	}
}

func isNameChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// numberAfterOK: char after digit run must be space/tab/EOL/']' (not before '=' etc.)
func lexBash(content string) []token {
	b := &bashCtx{s: content}
	n := len(content)
	arithDepth := 0 // inside $(( ))
	var braceStack []byte
	_ = braceStack
	for b.pos < n {
		c := content[b.pos]
		// newline handling
		if c == '\n' {
			// append to Text run if non-empty, else separate Text "\n"
			if b.textSB.Len() > 0 {
				b.textSB.WriteByte('\n')
				b.flushText()
			} else {
				// check last token: if last is Text (shouldn't happen since flushed)... 
				// Actually if textSB empty, previous token (if any) was non-Text or start.
				// Emit separate Text "\n".
				b.toks = append(b.toks, token{"Text", "\n"})
			}
			b.pos++
			continue
		}
		// comment?
		if c == '#' && isCommentStart(content, b.pos) {
			// comment to EOL (not incl \n)
			j := b.pos
			for j < n && content[j] != '\n' {
				j++
			}
			b.addTok("Comment", content[b.pos:j])
			b.pos = j
			continue
		}
		// single quote
		if c == '\'' {
			j := b.pos + 1
			for j < n && content[j] != '\'' {
				j++
			}
			if j < n {
				// closed (j is closing quote; backslash literal inside)
				b.addTok("String", content[b.pos:j+1])
				b.pos = j + 1
			} else {
				// unclosed: Error on quote, rest normal
				b.addTok("Error", "'")
				b.pos++
			}
			continue
		}
		// double quote (with $ interpolation, spans lines)
		if c == '"' {
			b.lexBashDquote()
			continue
		}
		// backtick
		if c == '`' {
			j := b.pos + 1
			for j < n && content[j] != '`' && content[j] != '\n' {
				j++
			}
			if j < n && content[j] == '`' {
				b.addTok("String", "`")
				if j > b.pos+1 {
					// content tokenized? Observed `ls` -> `(186) ls(231) `(186). Content "ls" is 231.
					// For complex content? Simplify: content as Text.
					b.addTok("Text", content[b.pos+1:j])
				}
				b.addTok("String", "`")
				b.pos = j + 1
			} else {
				// unclosed (EOL or EOF): ` alone 186, rest normal
				b.addTok("String", "`")
				b.pos++
			}
			continue
		}
		// backslash escape
		if c == '\\' {
			if b.pos+1 < n && content[b.pos+1] != '\n' {
				b.addTok("Number", content[b.pos:b.pos+2])
				b.pos += 2
			} else {
				b.addTok("Number", "\\")
				b.pos++
			}
			continue
		}
		// $ variables / expansions
		if c == '$' {
			if b.lexBashDollar(&arithDepth) {
				continue
			}
			// lone $: Text
			b.addText("$")
			b.pos++
			continue
		}
		// arithmetic context ops
		if arithDepth > 0 {
			if t, l := matchArithOp(content, b.pos); l > 0 {
				b.addTok(t, content[b.pos:b.pos+l])
				b.pos += l
				continue
			}
		}
		// operators (197): ==/===/=, &&, ||, parens, braces, brackets
		if t, l := matchBashOp(content, b.pos); l > 0 {
			// track $(( )) handled in dollar; plain parens here
			b.addTok(t, content[b.pos:b.pos+l])
			b.pos += l
			continue
		}
		// separators (231 but separate): ;;, ;&, ;, &, | (not ||/&& handled above)
		if t, l := matchBashSep(content, b.pos); l > 0 {
			b.addTok(t, content[b.pos:b.pos+l])
			b.pos += l
			continue
		}
		// numbers
		if isDigit(c) {
			if num, l := matchBashNumber(content, b.pos); l > 0 {
				b.addTok("Number", num)
				b.pos += l
				continue
			}
		}
		// words (keywords/builtins)
		if isNameChar(c) && !(isDigit(c)) {
			j := b.pos
			for j < n && isNameChar(content[j]) {
				j++
			}
			word := content[b.pos:j]
			// check word boundary after (must not be followed by name char - already maximal)
			if bashKeywords[word] {
				b.addTok("Keyword", word)
			} else if bashBuiltins[word] {
				b.addTok("Name", word)
			} else {
				b.addText(word)
			}
			b.pos = j
			continue
		}
		// default: Text char
		b.addText(string([]byte{c}))
		b.pos++
	}
	b.flushText()
	// Now fix trailing-\n attachment: Text runs ending with \n stay; but our loop
	// appended \n to non-empty runs and emitted separate for empty. However, there's
	// a subtlety: after a non-Text token, if next line starts... no, handled per \n.
	// One more: Text run followed by \n then more text on next line: "a\nb\n" ->
	// Text "a\n", Text "b\n". Our loop: 'a' -> run; \n -> append+flush ("a\n"); 'b' -> run; \n -> ("b\n"). Good.
	return b.toks
}

func isCommentStart(s string, pos int) bool {
	if pos == 0 {
		return true
	}
	prev := s[pos-1]
	if prev == '\n' || prev == ' ' || prev == '\t' {
		return true
	}
	switch prev {
	case ';', '&', '|', '(', ')', '[', ']', '<', '>', '`':
		return true
	}
	return false
}

// lexBashDquote lexes a double-quoted string with $ interpolation. pos at opening ".
func (b *bashCtx) lexBashDquote() {
	s := b.s
	n := len(s)
	// accumulate string parts, splitting around $vars/$()/etc.
	var part strings.Builder
	part.WriteByte('"')
	i := b.pos + 1
	flushPart := func() {
		if part.Len() > 0 {
			b.addTok("String", part.String())
			part.Reset()
		}
	}
	for i < n {
		c := s[i]
		if c == '"' {
			part.WriteByte('"')
			flushPart()
			b.pos = i + 1
			return
		}
		if c == '\\' {
			// inside dquotes backslash is literal part of string (2 chars if possible)
			if i+1 < n && s[i+1] != '\n' {
				part.WriteByte('\\')
				part.WriteByte(s[i+1])
				i += 2
			} else if i+1 < n {
				// backslash-newline? In shell, line continuation. Lexer? Probably 2 chars incl \n?
				// Untested. Treat backslash + newline as... hmm. Let me include both in string.
				part.WriteByte('\\')
				part.WriteByte('\n')
				i += 2
			} else {
				part.WriteByte('\\')
				i++
			}
			continue
		}
		if c == '$' {
			// var inside dquotes?
			if name, l := matchDollarVar(s, i); l > 0 {
				flushPart()
				// check adjacent merge ($x$y)? inside dquotes too? assume yes
				j := i + l
				for {
					if n2, l2 := matchDollarVar(s, j); l2 > 0 && j == i+l {
						// only merge if immediately adjacent (no gap) - j==i+l means adjacent
						l += l2
						j += l2
					} else {
						break
					}
				}
				b.addTok("Text", s[i:i+l])
				i += l
				_ = name
				continue
			}
			if s[i+1:] != "" {
				if strings.HasPrefix(s[i:], "$(") {
					// $(...) or $((...)) inside dquotes
					flushPart()
					// find matching close (simplified: scan with depth for parens)
					end := findDollarParenEnd(s, i)
					inner := s[i:end]
					// emit $( / $(( as Keyword, inner as...? For "$(b)": $(, b, ). Tokenize inner simply as Text? "b" was Text.
					// For complex inner, approximate: emit opener, inner Text, closer.
					if strings.HasPrefix(inner, "$((") {
						b.addTok("Keyword", "$((")
						mid := inner[3 : len(inner)-2]
						if mid != "" {
							b.addTok("Text", mid)
						}
						b.addTok("Keyword", "))")
					} else {
						b.addTok("Keyword", "$(")
						mid := inner[2 : len(inner)-1]
						if mid != "" {
							b.addTok("Text", mid)
						}
						b.addTok("Keyword", ")")
					}
					i = end
					continue
				}
				if strings.HasPrefix(s[i:], "${") {
					flushPart()
					end := findBraceEnd(s, i+2)
					b.lexBashBraceContent(s[i:end])
					i = end
					continue
				}
			}
			part.WriteByte('$')
			i++
			continue
		}
		if c == '`' {
			// literal inside dquotes
			part.WriteByte('`')
			i++
			continue
		}
		part.WriteByte(c)
		i++
	}
	// unclosed: rest is string
	flushPart()
	b.pos = n
}

// lexBashDollar handles $... at pos. Returns true if consumed (emitted tokens).
func (b *bashCtx) lexBashDollar(arithDepth *int) bool {
	s := b.s
	n := len(s)
	i := b.pos
	if i+1 >= n {
		return false
	}
	nxt := s[i+1]
	// $(( arithmetic
	if nxt == '(' && i+2 < n && s[i+2] == '(' {
		b.addTok("Keyword", "$((")
		b.pos = i + 3
		// lex until matching "))" with arithmetic rules
		*arithDepth++
		b.lexArith()
		*arithDepth--
		return true
	}
	// $( command
	if nxt == '(' {
		b.addTok("Keyword", "$(")
		b.pos = i + 2
		// lex until matching ')' (depth-aware, simplified: no nesting except quotes)
		depth := 1
		for b.pos < n && depth > 0 {
			cc := s[b.pos]
			if cc == '(' {
				depth++
				b.addTok("Operator", "(")
				b.pos++
				continue
			}
			if cc == ')' {
				depth--
				if depth == 0 {
					b.addTok("Keyword", ")")
					b.pos++
					break
				}
				b.addTok("Operator", ")")
				b.pos++
				continue
			}
			// inside $(): tokenize normally? "ls" was Text. Use simplified: quotes/vars/ops as normal via sub-lex?
			// For simplicity, lex inner with a sub-context for non-paren content.
			// Find next paren/quote/dollar and emit Text runs + specials.
			// Simplest: handle quotes, dollars, else Text until paren.
			if cc == '\'' || cc == '"' || cc == '`' || cc == '\\' || cc == '$' || cc == '#' || cc == '\n' {
				// reuse main loop by... hmm, recursion complexity. Handle minimal:
				if cc == '\n' {
					if b.textSB.Len() > 0 {
						b.textSB.WriteByte('\n')
						b.flushText()
					} else {
						b.toks = append(b.toks, token{"Text", "\n"})
					}
					b.pos++
					continue
				}
				// for quotes etc, break out and let main loop handle? No - main loop doesn't know depth.
				// Handle '$' vars simply:
				if cc == '$' {
					if b.lexBashDollar(arithDepth) {
						continue
					}
					b.addText("$")
					b.pos++
					continue
				}
				// quotes: emit as string simply (no nesting)
				if cc == '\'' {
					j := b.pos + 1
					for j < n && s[j] != '\'' {
						j++
					}
					if j < n {
						b.addTok("String", s[b.pos:j+1])
						b.pos = j + 1
					} else {
						b.addTok("Error", "'")
						b.pos++
					}
					continue
				}
				if cc == '"' {
					b.lexBashDquote()
					continue
				}
				if cc == '`' {
					b.addTok("String", "`")
					b.pos++
					continue
				}
				if cc == '\\' {
					if b.pos+1 < n && s[b.pos+1] != '\n' {
						b.addTok("Number", s[b.pos:b.pos+2])
						b.pos += 2
					} else {
						b.addTok("Number", "\\")
						b.pos++
					}
					continue
				}
				if cc == '#' && isCommentStart(s, b.pos) {
					j := b.pos
					for j < n && s[j] != '\n' {
						j++
					}
					b.addTok("Comment", s[b.pos:j])
					b.pos = j
					continue
				}
			}
			// operators inside $()? e.g. $(a=b)? Probably same as normal. Handle = and seps.
			if t, l := matchBashOp(s, b.pos); l > 0 {
				// avoid consuming ')' here (handled above)? matchBashOp includes parens; but we handle parens above.
				// '(' handled above too. So skip paren ops here.
				op := s[b.pos : b.pos+l]
				if op == "(" || op == ")" {
					b.addText(op)
					b.pos += l
					continue
				}
				b.addTok(t, op)
				b.pos += l
				continue
			}
			if t, l := matchBashSep(s, b.pos); l > 0 {
				b.addTok(t, s[b.pos:b.pos+l])
				b.pos += l
				continue
			}
			if isDigit(cc) {
				if num, l := matchBashNumber(s, b.pos); l > 0 {
					b.addTok("Number", num)
					b.pos += l
					continue
				}
			}
			if isNameChar(cc) && !isDigit(cc) {
				j := b.pos
				for j < n && isNameChar(s[j]) {
					j++
				}
				word := s[b.pos:j]
				if bashKeywords[word] {
					b.addTok("Keyword", word)
				} else if bashBuiltins[word] {
					b.addTok("Name", word)
				} else {
					b.addText(word)
				}
				b.pos = j
				continue
			}
			b.addText(string([]byte{cc}))
			b.pos++
		}
		return true
	}
	// ${...}
	if nxt == '{' {
		end := findBraceEnd(s, i+2)
		b.lexBashBraceContent(s[i:end])
		b.pos = end
		return true
	}
	// $'...' / $"..."
	if nxt == '\'' || nxt == '"' {
		// string with $ prefix
		q := nxt
		j := i + 2
		for j < n && s[j] != q {
			j++
		}
		if j < n {
			b.addTok("String", s[i:j+1])
			b.pos = j + 1
		} else {
			// unclosed: $' + rest? For $"unclosed? Probably String to EOL. For $'unclosed? Hmm.
			// Treat like quote: $" -> String to EOL; $' -> Error on '? Untested. Use: String from $ to EOL.
			k := i
			for k < n && s[k] != '\n' {
				k++
			}
			b.addTok("String", s[i:k])
			b.pos = k
		}
		return true
	}
	// $var / $special (with adjacent merge)
	if name, l := matchDollarVar(s, i); l > 0 {
		j := i + l
		for {
			if _, l2 := matchDollarVar(s, j); l2 > 0 {
				l += l2
				j += l2
			} else {
				break
			}
		}
		b.addTok("Text", s[i:i+l])
		_ = name
		return true
	}
	return false
}

// matchDollarVar matches $NAME or $special at pos. Returns (text, length) or ("",0).
func matchDollarVar(s string, pos int) (string, int) {
	if pos >= len(s) || s[pos] != '$' || pos+1 >= len(s) {
		return "", 0
	}
	c := s[pos+1]
	if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || (c >= '0' && c <= '9') {
		j := pos + 1
		for j < len(s) && isNameChar(s[j]) {
			j++
		}
		return s[pos:j], j - pos
	}
	switch c {
	case '@', '*', '?', '#', '$', '!', '-', ' ':
		// '$ ' (dollar-space)? No - lone $. Exclude space.
		if c == ' ' {
			return "", 0
		}
		return s[pos : pos+2], 2
	}
	return "", 0
}

func findDollarParenEnd(s string, start int) int {
	// start at '$', s[start:start+2]=="$(" (not $ lah). Find matching ')' with depth, quote-aware-ish.
	n := len(s)
	depth := 0
	i := start
	var inS, inD bool
	for i < n {
		c := s[i]
		if inS {
			if c == '\'' {
				inS = false
			}
			i++
			continue
		}
		if inD {
			if c == '\\' {
				i += 2
				continue
			}
			if c == '"' {
				inD = false
			}
			i++
			continue
		}
		if c == '\'' {
			inS = true
			i++
			continue
		}
		if c == '"' {
			inD = true
			i++
			continue
		}
		if c == '(' {
			depth++
		} else if c == ')' {
			depth--
			if depth == 0 {
				return i + 1
			}
		}
		i++
	}
	return n
}

func findBraceEnd(s string, start int) int {
	// start after "${". Find first '}' (no nesting).
	n := len(s)
	for i := start; i < n; i++ {
		if s[i] == '}' {
			return i + 1
		}
	}
	return n
}

// lexBashBraceContent lexes "${...}" (text from $ to }). Handles ${#, :-, ops.
func (b *bashCtx) lexBashBraceContent(s string) {
	// s starts with "${"
	if len(s) < 3 {
		b.addTok("String", s)
		return
	}
	rest := s[2:]
	opener := "${"
	if strings.HasPrefix(rest, "#") {
		opener = "${#"
		rest = rest[1:]
	}
	b.addTok("String", opener)
	// rest ends with '}' (or unterminated)
	inner := rest
	closed := false
	if strings.HasSuffix(inner, "}") && len(inner) >= 1 {
		inner = inner[:len(inner)-1]
		closed = true
	}
	// find ":-" (only special op, 81); everything else Text runs?
	if idx := strings.Index(inner, ":-"); idx >= 0 {
		if idx > 0 {
			b.addTok("Text", inner[:idx])
		}
		b.addTok("Keyword", ":-")
		if idx+2 < len(inner) {
			b.addTok("Text", inner[idx+2:])
		}
	} else if inner != "" {
		b.addTok("Text", inner)
	}
	if closed {
		b.addTok("String", "}")
	}
}

// lexArith lexes inside $(( )) until matching )).
func (b *bashCtx) lexArith() {
	s := b.s
	n := len(s)
	for b.pos < n {
		if strings.HasPrefix(s[b.pos:], "))") {
			b.addTok("Keyword", "))")
			b.pos += 2
			return
		}
		c := s[b.pos]
		if c == '\n' {
			if b.textSB.Len() > 0 {
				b.textSB.WriteByte('\n')
				b.flushText()
			} else {
				b.toks = append(b.toks, token{"Text", "\n"})
			}
			b.pos++
			continue
		}
		// numbers
		if isDigit(c) {
			j := b.pos
			for j < n && isDigit(s[j]) {
				j++
			}
			// in arith, numbers always Number? "1+2": 1,2 Number. Assume yes (followed by anything?).
			b.addTok("Number", s[b.pos:j])
			b.pos = j
			continue
		}
		// arith ops
		if t, l := matchArithOp(s, b.pos); l > 0 {
			b.addTok(t, s[b.pos:b.pos+l])
			b.pos += l
			continue
		}
		// $vars inside?
		if c == '$' {
			var dummy int
			if b.lexBashDollar(&dummy) {
				continue
			}
			b.addText("$")
			b.pos++
			continue
		}
		// quotes? strings? Keep simple: Text.
		// words: Text runs (names)
		b.addText(string([]byte{c}))
		b.pos++
	}
}

// matchArithOp matches arithmetic operators (197), longest first.
func matchArithOp(s string, pos int) (string, int) {
	rest := s[pos:]
	ops := []string{"**", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<=", ">>=", "++", "--", "+", "-", "*", "/", "%", "<", ">", "&", "|", "^", "!", "~", "?", ":", ",", "(", ")"}
	// Note: "))" handled by caller (close). Single ")" here? In arith, parens 197? Guess.
	for _, op := range ops {
		if strings.HasPrefix(rest, op) {
			// avoid matching ")" of "))" close? Caller checks "))" first, so single ")" only when not followed by ")".
			// But "))" could also be two closes? Only one level here. Fine.
			// Avoid matching ">" of ">>"? longest-first handles.
			return "Operator", len(op)
		}
	}
	return "", 0
}

// matchBashOp matches 197 operators at pos. Returns (type, length).
func matchBashOp(s string, pos int) (string, int) {
	c := s[pos]
	switch c {
	case '=':
		j := pos
		for j < len(s) && s[j] == '=' {
			j++
		}
		return "Operator", j - pos
	case '&':
		if pos+1 < len(s) && s[pos+1] == '&' {
			return "Operator", 2
		}
		return "", 0
	case '|':
		if pos+1 < len(s) && s[pos+1] == '|' {
			return "Operator", 2
		}
		return "", 0
	case '(':
		if pos+1 < len(s) && s[pos+1] == '(' {
			return "Operator", 2
		}
		return "Operator", 1
	case ')':
		if pos+1 < len(s) && s[pos+1] == ')' {
			return "Operator", 2
		}
		return "Operator", 1
	case '{', '}':
		return "Operator", 1
	case '[':
		if pos+1 < len(s) && s[pos+1] == '[' {
			return "Operator", 2
		}
		return "Operator", 1
	case ']':
		if pos+1 < len(s) && s[pos+1] == ']' {
			return "Operator", 2
		}
		return "Operator", 1
	}
	return "", 0
}

// matchBashSep matches separators that are separate 231 tokens: ;;, ;&, ;, &, |
func matchBashSep(s string, pos int) (string, int) {
	c := s[pos]
	switch c {
	case ';':
		if strings.HasPrefix(s[pos:], ";;&") {
			return "Text", 3
		}
		if pos+1 < len(s) && (s[pos+1] == ';' || s[pos+1] == '&') {
			return "Text", 2
		}
		return "Text", 1
	case '&':
		// && handled as op before; single & here
		return "Text", 1
	case '|':
		// || handled before; single | here
		return "Text", 1
	}
	return "", 0
}

// matchBashNumber matches a Number (digits) if valid: after must be space/tab/EOL/']'
// and not followed (after spaces?) by '='. Before: not alnum/_/. (caller ensures start or checked?)
func matchBashNumber(s string, pos int) (string, int) {
	// caller guarantees s[pos] is digit; check before: must not be alnum/_ (would be part of word)
	if pos > 0 {
		prev := s[pos-1]
		if isNameChar(prev) || prev == '.' {
			return "", 0
		}
	}
	j := pos
	for j < len(s) && isDigit(s[j]) {
		j++
	}
	num := s[pos:j]
	// after check
	if j < len(s) {
		after := s[j]
		if after == ' ' || after == '\t' || after == '\n' || after == ']' {
			// also not followed by spaces+= ? check "1 ="
			if after == ' ' || after == '\t' {
				k := j
				for k < len(s) && (s[k] == ' ' || s[k] == '\t') {
					k++
				}
				if k < len(s) && s[k] == '=' {
					return "", 0
				}
			}
			return num, j - pos
		}
		return "", 0
	}
	return num, j - pos
}
