// lexHashComment: lines with # comments, quotes, numbers, words.
func lexHashComment(content string, kw, bi map[string]bool) []token {
	if content == "" {
		return nil
	}
	var toks []token
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			toks = append(toks, token{"Text", cur.String()})
			cur.Reset()
		}
	}
	i := 0
	n := len(content)
	for i < n {
		c := content[i]
		if c == '\n' {
			if cur.Len() > 0 {
				cur.WriteByte('\n')
				flush()
			} else {
				toks = append(toks, token{"Text", "\n"})
			}
			i++
			continue
		}
		if c == '#' {
			j := i
			for j < n && content[j] != '\n' {
				j++
			}
			if cur.Len() > 0 {
				flush()
			}
			toks = append(toks, token{"Comment", content[i:j]})
			i = j
			continue
		}
