			q := c
			j := i + 1
			for j < n && content[j] != q && content[j] != '\n' {
				if content[j] == '\\' {
					j++
				}
				j++
			}
			if cur.Len() > 0 {
				flush()
			}
			if j < n && content[j] == q {
				toks = append(toks, token{"String", content[i : j+1]})
				i = j + 1
			} else {
				toks = append(toks, token{"String", content[i:j]})
				i = j
			}
			continue
		}
		if isDigit(c) {
			j := i
			for j < n && (isDigit(content[j]) || content[j] == '.') {
				j++
			}
			if cur.Len() > 0 {
				flush()
			}
			toks = append(toks, token{"Number", content[i:j]})
			i = j
			continue
		}
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' {
			j := i
			for j < n && (isNameChar(content[j])) {
				j++
			}
			word := content[i:j]
			if cur.Len() > 0 {
				flush()
			}
			if kw[word] {
