func isBareValueFlag(tok string) bool {
	if strings.HasPrefix(tok, "--") {
		d := byLong[tok[2:]]
		return d != nil && !d.isBool
	}
	if len(tok) == 2 && tok[0] == '-' {
		d := byShort[tok[1]]
		return d != nil && !d.isBool
	}
	return false
}

