package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

// runComplete implements the hidden __complete command (cobra-compatible).
func runComplete(cargs []string) int {
	if len(cargs) == 0 {
		fmt.Fprintln(os.Stderr, "requires at least 1 arg(s), only received 0")
		return 1
	}
	toComplete := cargs[len(cargs)-1]
	rest := cargs[:len(cargs)-1]

	// Case 1: toComplete contains "=" and starts with "-" -> flag value completion or :0.
	if strings.HasPrefix(toComplete, "-") && strings.Contains(toComplete, "=") {
		out, directive := completeEquals(toComplete)
		printComplete(out, directive)
		return 0
	}

	// Parse rest (with completion-specific rules).
	cp, perr := parseCompleteArgs(rest, toComplete)
	if perr != "" {
		fmt.Fprintf(os.Stderr, "[Debug] [Error] %s\n", perr.cobraMsg)
		fmt.Fprintln(os.Stdout, ":0")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
		return 0
	}
	_ = cp
	// Help suppresses everything.
	if cp.helpSet {
		fmt.Fprintln(os.Stdout, ":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	}

	// Case 2: toComplete starts with "-" -> flag name completion.
	if strings.HasPrefix(toComplete, "-") {
		out := completeFlagNames(toComplete)
		printComplete(out, 4)
		return 0
	}

	// Case 3: previous flag needs value -> complete its values.
	if cp.pending != "" {
		out, directive := completeFlagValue(cp.pending)
		printComplete(out, directive)
		return 0
	}

	// Case 4: positional already present -> empty.
	if len(cp.positionals) >= 1 {
		// special case: rest == ["--", <bare value flag>] (single) -> sheets
		if isLoneValueFlagAfterDashDash(rest) {
			out := completeSheets()
			printComplete(out, 4)
			return 0
		}
		fmt.Fprintln(os.Stdout, ":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	}

	// Case 5: sheets.
	out := completeSheets()
	printComplete(out, 4)
	return 0
}

func isLoneValueFlagAfterDashDash(rest []string) bool {
	// find "--"; post-dashdash args must be exactly [single bare value flag], no pre positionals counted separately.
	// Simpler: rest (raw) must be [...flags(no positionals)..., "--", X] with X bare value flag and exactly one post--- arg.
	dashIdx := -1
	for i, t := range rest {
		if t == "--" {
			dashIdx = i
			break
		}
	}
	if dashIdx < 0 {
		return false
	}
	post := rest[dashIdx+1:]
	if len(post) != 1 {
		return false
	}
	return isBareValueFlag(post[0])
}

func isBareValueFlag(tok string) bool {
	if strings.HasPrefix(tok, "--") {
		d := byLong[tok[2:]]
		return d != nil && !d.isBool
	}
	if len(tok) == 2 && tok[0] == '-' {
		d := byShort[tok[1]]
		return d != nil && !d.isBool
	}
	return false
}

func printComplete(lines []string, directive int) {
	for _, l := range lines {
		fmt.Fprintln(os.Stdout, l)
	}
	fmt.Fprintf(os.Stdout, ":%d\n", directive)
	if directive == 4 {
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
	} else {
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
	}
}

// completeEquals handles toComplete with "=" (starts with -).
func completeEquals(toComplete string) ([]string, int) {
	if strings.HasPrefix(toComplete, "--") {
		eq := strings.IndexByte(toComplete, '=')
		name := toComplete[2:eq]
		if name == "" {
			// "--=x" -> sheets!
			return completeSheets(), 4
		}
		d := byLong[name]
		if d == nil {
			return nil, 0
		}
		if d.isBool {
			return nil, 0
		}
		return completeFlagValue(d.long)
	}
	// short: "-X=..."
	if len(toComplete) < 2 {
		return nil, 0
	}
	c := toComplete[1]
	d := byShort[c]
	if d == nil {
		return nil, 0
	}
	if d.isBool {
		return nil, 0
	}
	return completeFlagValue(d.long)
}

// completeFlagNames lists flags matching prefix toComplete.
func completeFlagNames(toComplete string) []string {
	var out []string
	if toComplete == "-" {
		for i := range flagDefs {
			d := &flagDefs[i]
			out = append(out, "--"+d.long+"\t"+d.usage)
			if d.short != 0 {
				out = append(out, fmt.Sprintf("-%c\t%s", d.short, d.usage))
			}
		}
		return out
	}
	if toComplete == "--" {
		for i := range flagDefs {
			d := &flagDefs[i]
			out = append(out, "--"+d.long+"\t"+d.usage)
		}
		return out
	}
	if strings.HasPrefix(toComplete, "--") {
		for i := range flagDefs {
			d := &flagDefs[i]
			if strings.HasPrefix("--"+d.long, toComplete) {
				out = append(out, "--"+d.long+"\t"+d.usage)
			}
		}
		return out
	}
	// short: exact 2-char match only
	if len(toComplete) == 2 {
		if d := byShort[toComplete[1]]; d != nil {
			out = append(out, fmt.Sprintf("-%c\t%s", toComplete[1], d.usage))
		}
	}
	return out
}

// completeFlagValue returns value completions for a value flag (by long name).
func completeFlagValue(long string) ([]string, int) {
	switch long {
	case "path":
		return completePaths(), 4
	case "tag":
		return completeTags(), 4
	case "edit", "rm":
		return completeSheets(), 4
	case "search", "completion":
		return nil, 0
	}
	return nil, 0
}

// --- completion data (config errors swallowed, warnings printed) ---

func completeSheets() []string {
	all := loadSheetsQuiet()
	seen := map[string]bool{}
	var out []string
	for _, s := range all {
		if !seen[s.title] {
			seen[s.title] = true
			out = append(out, s.title)
		}
	}
	return out
}

func completePaths() []string {
	cfg := loadConfigQuiet()
	var out []string
	if cfg == nil {
		return out
	}
	for _, rp := range cfg.paths {
		out = append(out, rp.name)
	}
	return out
}

func completeTags() []string {
	all := loadSheetsQuiet()
	seen := map[string]bool{}
	var out []string
	for _, s := range all {
		for _, t := range s.tags {
			if !seen[t] {
				seen[t] = true
				out = append(out, t)
			}
		}
	}
	// sort? Observed tags sorted (Apple,PathTag,apple,...). loadSheets sorts sheets, but tags across sheets need sort.
	sortStrings(out)
	return out
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// loadConfigQuiet loads config for completion: warnings printed, errors swallowed.
func loadConfigQuiet() *loadedConfig {
	path := findConfigPath()
	if path == "" {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	root, err := parseYAMLDoc(string(data))
	if err != nil {
		return nil
	}
	cf, derrs := decodeConfig(root)
	if len(derrs) > 0 {
		return nil
	}
	cfg, errStr := validateConfigQuiet(cf, path)
	if errStr != "" {
		return nil
	}
	return cfg
}

// validateConfigQuiet is validateConfig but returns "" config on error (warnings still printed).
func validateConfigQuiet(cf *configFile, confPath string) (*loadedConfig, string) {
	// Temporarily capture? validateConfig prints warnings to stderr (desired) and returns errStr.
	return validateConfig(cf, confPath)
}

func loadSheetsQuiet() []sheet {
	cfg := loadConfigQuiet()
	if cfg == nil {
		return nil
	}
	all, errStr := loadSheets(cfg)
	if errStr != "" {
		return nil
	}
	return all
}

// --- complete arg parsing ---

type completeParsed struct {
	helpSet     bool
	pending     string // long name of value flag needing value (toComplete is its value), or ""
	positionals []string
}

type completeErr struct {
	cobraMsg string // full message after "[Debug] [Error] "
}

// parseCompleteArgs parses rest (args before toComplete) with completion rules.
// consumedUpTo tracks tokens consumed for the "from args [...]" list.
func parseCompleteArgs(rest []string, toComplete string) (*completeParsed, *completeErr) {
	cp := &completeParsed{}
	// consumedList for error reporting (tokens up to and including failing)
	i := 0
	dashdash := false
	for i < len(rest) {
		tok := rest[i]
		isLast := i == len(rest)-1
		if dashdash {
			cp.positionals = append(cp.positionals, tok)
			i++
			continue
		}
		if tok == "--" {
			dashdash = true
			i++
			continue
		}
		if tok == "-" || !strings.HasPrefix(tok, "-") {
			cp.positionals = append(cp.positionals, tok)
			i++
			continue
		}
		if strings.HasPrefix(tok, "--") {
			name := tok[2:]
			val := ""
			hasVal := false
			if idx := strings.IndexByte(name, '='); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}
			d := byLong[name]
			if d == nil {
				return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: unknown flag: --%s", joinArgs(rest, i), name)}
			}
			if d.isBool {
				if hasVal {
					if _, err := strconv.ParseBool(val); err != nil {
						return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: invalid argument %q for %s flag: %v", joinArgs(rest, i), val, boolFlagLabel(d), err)}
					}
				}
				if d.long == "help" {
					cp.helpSet = true
				}
				i++
				continue
			}
			// value flag
			if hasVal {
				i++
				continue
			}
			// needs next
			if i+1 >= len(rest) {
				// pending: toComplete is value
				if strings.HasPrefix(toComplete, "-") {
					// toComplete flag-like -> needs argument error
					return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: flag needs an argument: --%s", joinArgs(rest, i), name)}
				}
				cp.pending = d.long
				i++
				continue
			}
			next := rest[i+1]
			nextIsLast := i+1 == len(rest)-1
			if !nextIsLast {
				// blind consume
				i += 2
				continue
			}
			// next is last-before-toComplete: apply Y rules
			if yerr := checkPostValueY(d, next); yerr != "" {
				return nil, &completeErr{yerr}
			}
			i += 2
			continue
		}
		// short bundle
		sh := tok[1:]
		j := 0
		consumedNext := false
		for j < len(sh) {
			c := sh[j]
			d := byShort[c]
			if d == nil {
				return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: unknown shorthand flag: '%c' in -%s", joinArgs(rest, i), c, sh[j:])}
			}
			if d.isBool {
				rem := sh[j:]
				if len(rem) > 2 && rem[1] == '=' {
					v := rem[2:]
					if _, err := strconv.ParseBool(v); err != nil {
						return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: invalid argument %q for %s flag: %v", joinArgs(rest, i), v, boolFlagLabel(d), err)}
					}
					j = len(sh)
					break
				}
				if d.long == "help" {
					cp.helpSet = true
				}
				j++
				continue
			}
			// value flag
			attached := sh[j+1:]
			if attached != "" {
				if strings.HasPrefix(attached, "=") {
					// verbatim value, no check
				} else {
					// last-char check
					last := attached[len(attached)-1]
					if byShort[last] == nil {
						return nil, &completeErr{fmt.Sprintf("Subcommand 'cheat' does not support flag '%c'", last)}
					}
				}
				j = len(sh)
				break
			}
			// needs next token
			if i+1 >= len(rest) {
				if strings.HasPrefix(toComplete, "-") {
					return nil, &completeErr{fmt.Sprintf("Error while parsing flags from args [%s]: flag needs an argument: '%c' in -%c", joinArgs(rest, i), c, c)}
				}
				cp.pending = d.long
				consumedNext = true // toComplete consumed; stop parsing rest
				j = len(sh)
				break
			}
			next := rest[i+1]
			nextIsLast := i+1 == len(rest)-1
			if !nextIsLast {
				consumedNext = true
				j = len(sh)
				break
			}
			if yerr := checkPostValueY(d, next); yerr != "" {
				return nil, &completeErr{yerr}
			}
			consumedNext = true
			j = len(sh)
			break
		}
		if consumedNext {
			i += 2
		} else {
			i++
		}
	}
	return cp, nil
}

func joinArgs(rest []string, upto int) string {
	return strings.Join(rest[:upto+1], " ")
}

// checkPostValueY applies completion Y-rules for value-flag followed by last-before token.
// Returns "" if consumed, else the cobra/parse error message (without [Debug] prefix).
func checkPostValueY(d *flagDef, next string) string {
	_ = d
	if strings.Contains(next, "=") && strings.HasPrefix(next, "-") {
		return "" // consume blindly
	}
	if next == "--" || next == "-" || !strings.HasPrefix(next, "-") {
		return "" // consume
	}
	if strings.HasPrefix(next, "--") {
		name := next[2:]
		dd := byLong[name]
		if dd == nil {
			return fmt.Sprintf("Subcommand 'cheat' does not support flag '%s'", name)
		}
		if dd.isBool {
			return "" // consume
		}
		// bare value flag -> needs argument error citing d
		if d.short != 0 {
			// d could be long or short; cite as parsed? The error cites the FIRST flag as written?
			// Observed: "-e -p" -> "flag needs an argument: 'e' in -e" (short form).
			// "--path --path" -> "flag needs an argument: --path" (long form).
			// So cite by how d was written. We lost that info; approximate: prefer short? No -
			// need to track. For now: if d has short, use short form? But "--path --path" used long!
			// Must track written form. Handled by caller passing written form? Simplify: check both?
		}
		return "NEEDSARG:" + d.long
	}
	// short: exact known?
	if len(next) == 2 {
		dd := byShort[next[1]]
		if dd == nil {
			return fmt.Sprintf("Subcommand 'cheat' does not support flag '%c'", next[1])
		}
		if dd.isBool {
			return ""
		}
		return "NEEDSARG:" + d.long
	}
	// bundle: last-char check
	last := next[len(next)-1]
	if byShort[last] == nil {
		return fmt.Sprintf("Subcommand 'cheat' does not support flag '%c'", last)
	}
	return ""
}
EOF
