newfunc = '''// parseFlow parses flow seq/map, possibly spanning multiple lines starting at
// the given line. Continuation lines are consumed by blanking them.
func (p *yParser) parseFlow(first string, lineNo int, open byte, nextIdx, end, ind int) (*yNode, error) {
	startPhys := lineNo - 1
	sepErr := func(phys int) error {
		// single-line: max(start,1); multi handled by caller passing last content phys+1?
		_ = phys
		if open == '[' {
			return &yError{phys, "did not find expected ',' or ']'"}
		}
		return &yError{phys, "did not find expected ',' or '}'"}
	}
	_ = sepErr
	depth := 0
	var inS, inD bool
	var consumed []int
	type partT struct {
		text string
		phys int
	}
	parts := []partT{{first, startPhys}}
	done := false
	scanEnd := 0
	// last significant char for EOF state (opener/comma/colon => node expected)
	lastSig := byte(open)
	li := 0
	cursor := nextIdx
	blocked := false
	for {
		var ln string
		var phys int
		if li == 0 {
			ln = first
			phys = startPhys
		} else {
			for cursor < end {
				t := p.lines[cursor]
				if strings.TrimSpace(t) == "" {
					cursor++
					continue
				}
				if !inS && !inD && strings.HasPrefix(strings.TrimSpace(t), "#") {
					cursor++
					continue
				}
				break
			}
			if cursor >= end {
				break // EOF -> unclosed handling below
			}
			raw := stripCommentFlow(p.lines[cursor], inS, inD)
			ln = strings.TrimSpace(raw)
			if ln == "" {
				cursor++
				continue
			}
			// key-like lines block continuation (unless in quotes)
			if !inS && !inD && isKeyLike(ln) {
				blocked = true
				break
			}
			phys = cursor
			consumed = append(consumed, cursor)
			cursor++
			parts = append(parts, partT{ln, phys})
		}
		closedHere := false
		for k := 0; k < len(ln); k++ {
			c := ln[k]
			if inS {
				if c == '\\'' {
					if k+1 < len(ln) && ln[k+1] == '\\'' {
						k++
						continue
					}
					inS = false
				}
				lastSig = c
				continue
			}
			if inD {
				if c == '\\\\' {
					k++
					lastSig = c
					continue
				}
				if c == '"' {
					inD = false
				}
				lastSig = c
				continue
			}
			if c == '\\'' {
				inS = true
				lastSig = c
				continue
			}
			if c == '"' {
				inD = true
				lastSig = c
				continue
			}
			if c == ' ' || c == '\\t' {
				continue
			}
			lastSig = c
			if c == '[' || c == '{' {
				depth++
				continue
			}
			if c == ']' || c == '}' {
				if depth == 0 {
					// extra closer
					if open == '[' {
						return nil, &yError{phys, "did not find expected ',' or ']'"}
					}
					return nil, &yError{phys, "did not find expected ',' or '}'"}
				}
				depth--
				if depth == 0 {
					if (open == '[' && c != ']') || (open == '{' && c != '}') {
						if open == '[' {
							return nil, &yError{phys, "did not find expected ',' or ']'"}
						}
						return nil, &yError{phys, "did not find expected ',' or '}'"}
					}
					done = true
					scanEnd = k
					_ = phys
					break
				}
				continue
			}
		}
		if done {
			trail := strings.TrimSpace(ln[scanEnd+1:])
			if trail != "" {
				return nil, &yError{phys, "did not find expected key"}
			}
			break
		}
		li++
		if li > 10000 {
			break
		}
	}
	if !done {
		// EOF (or blocked): unclosed. Determine node vs separator by lastSig.
		expectNode := lastSig == '[' || lastSig == '{' || lastSig == ',' || lastSig == ':'
		if expectNode {
			// node content: last content line (1-based)
			lastPhys := parts[len(parts)-1].phys
			return nil, &yError{lastPhys + 1, "did not find expected node content"}
		}
		// separator error
		if len(parts) == 1 {
			l := startPhys
			if l < 1 {
				l = 1
			}
			if open == '[' {
				return nil, &yError{l, "did not find expected ',' or ']'"}
			}
			return nil, &yError{l, "did not find expected ',' or '}'"}
		}
		lastPhys := parts[len(parts)-1].phys
		if open == '[' {
			return nil, &yError{lastPhys + 1, "did not find expected ',' or ']'"}
		}
		return nil, &yError{lastPhys + 1, "did not find expected ',' or '}'"}
	}
	_ = blocked
	var full strings.Builder
	var spans []lineSpan
	for i, pt := range parts {
		if i > 0 {
			full.WriteByte(' ')
		}
		spans = append(spans, lineSpan{full.Len(), pt.phys + 1})
		if i == len(parts)-1 {
			full.WriteString(pt.text[:scanEnd+1])
		} else {
			full.WriteString(pt.text)
		}
	}
	for _, idx := range consumed {
		p.lines[idx] = ""
	}
	return parseFlowTextSpans(full.String(), lineNo, p, spans)
}

// isKeyLike reports whether a continuation line looks like a block key (blocks flow).
func isKeyLike(ln string) bool {
	// contains ': ' or ':\\t' or ends with ':' (outside quotes - approximate: strip quotes)
	var sb strings.Builder
	var inS, inD bool
	for i := 0; i < len(ln); i++ {
		c := ln[i]
		if inS {
			if c == '\\'' {
				if i+1 < len(ln) && ln[i+1] == '\\'' {
					i++
					continue
				}
				inS = false
			}
			continue
		}
		if inD {
			if c == '\\\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		if c == '\\'' {
			inS = true
			continue
		}
		if c == '"' {
			inD = true
			continue
		}
		sb.WriteByte(c)
	}
	t := sb.String()
	if strings.HasSuffix(strings.TrimSpace(t), ":") {
		return true
	}
	for i := 0; i+1 < len(t); i++ {
		if t[i] == ':' && (t[i+1] == ' ' || t[i+1] == '\\t') {
			return true
		}
	}
	return false
}

'''
