		if inD {
			if c == '\\\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		if c == '\\'' {
			inS = true
			continue
		}
		if c == '"' {
			inD = true
			continue
		}
		sb.WriteByte(c)
	}
	t := sb.String()
	if strings.HasSuffix(strings.TrimSpace(t), ":") {
		return true
	}
	for i := 0; i+1 < len(t); i++ {
		if t[i] == ':' && (t[i+1] == ' ' || t[i+1] == '\\t') {
			return true
		}
	}
	return false
}

