		p.toks = append(p.toks, token{typ, s})
	}
}

func (p *progLexer) addTextRun(s string) {
	p.toks = append(p.toks, token{"Text", s})
}

var pyKw81 = map[string]bool{
	"and": false, // placeholder (actually 197)
}

func pythonKwClass(word string) string {
	switch word {
	case "and", "or", "not", "in", "is", "import", "from", "as":
		return "Keyword197"
	}
	switch word {
	case "assert", "break", "class", "continue", "def", "del", "elif", "else",
		"except", "finally", "for", "global", "if", "lambda", "nonlocal",
		"pass", "raise", "return", "try", "while", "with", "yield",
		"None", "True", "False":
		return "Keyword"
	}
	return ""
}

func lexPythonFull(content string) []token {
	p := &progLexer{s: content}
	n := len(content)
	prevWord := ""
	for p.pos < n {
		c := content[p.pos]
		if c == '\n' {
			// attach to previous Text run if last token is Text, else separate
			if len(p.toks) > 0 && p.toks[len(p.toks)-1].typ == "Text" {
				p.toks[len(p.toks)-1].text += "\n"
			} else {
				p.toks = append(p.toks, token{"Text", "\n"})
			}
			p.pos++
			prevWord = ""
			continue
		}
		if c == '#' {
			j := p.pos
			for j < n && content[j] != '\n' {
				j++
			}
			p.addTyp("Comment", content[p.pos:j])
			p.pos = j
			prevWord = ""
			continue
		}
		// strings (with prefixes r/b/u/f, triple quotes)
		if tok, l := matchPyString(content, p.pos); l > 0 {
			// f-string interpolation?
			emitPyString(p, tok)
			p.pos += l
			prevWord = ""
			continue
		}
		// decorator
		if c == '@' && p.pos+1 < n && isPyNameStart(content[p.pos+1]) {
			j := p.pos + 1
			for j < n && isNameChar(content[j]) {
				j++
			}
			p.addTyp("Name", content[p.pos:j])
			p.pos = j
			prevWord = ""
			continue
		}
		// numbers
		if isDigit(c) {
			if num, l := matchPyNumber(content, p.pos); l > 0 {
				p.addTyp("Number", num)
				p.pos += l
				prevWord = ""
				continue
			}
		}
		// words
		if isPyNameStart(c) {
			j := p.pos
			for j < n && isNameChar(content[j]) {
				j++
			}
			word := content[p.pos:j]
			if cls := pythonKwClass(word); cls == "Keyword" {
				p.addTyp("Keyword", word)
			} else if cls == "Keyword197" {
				p.addTyp("Operator", word)
			} else if (prevWord == "def" || prevWord == "class") {
				p.addTyp("Name", word)
			} else {
				p.addTyp("Text", word)
			}
			prevWord = word
			p.pos = j
			continue
		}
		// operators (multi-char)
		if op, l := matchPyOp(content, p.pos); l > 0 {
			p.addTyp("Operator", op)
			p.pos += l
			prevWord = ""
			continue
		}
		// punctuation (merged runs)
		if isPyPunct(c) {
			j := p.pos
			for j < n && isPyPunct(content[j]) {
				j++
			}
			p.addTyp("Punct", content[p.pos:j])
			p.pos = j
			prevWord = ""
			continue
		}
		// Text run (spaces and misc)
		j := p.pos
		for j < n {
			cc := content[j]
			if cc == '\n' || cc == '#' || cc == '"' || cc == '\'' {
				break
			}
			if cc == '@' && j+1 < n && isPyNameStart(content[j+1]) {
				break
			}
			if isDigit(cc) {
				// number start? check valid (not part of word - but words checked... digits after text?)
				// If previous char is name char, it's part of word - but we're in Text run, so previous was text.
				// A digit always starts number? "a1"? Hmm. In "a1", 'a' is word (Text), then '1'...?
				// Python: "a1" is one Name. But we tokenize 'a' as word first. Then '1' separate Number?
				// What does chroma do for "a1"? Probably Name "a1" (one token). Hmm.
				// To be safe: if previous char (in run) is name char or '.', include digit in run.
				if j > p.pos {
					prev := content[j-1]
					if isNameChar(prev) || prev == '.' {
						j++
						continue
					}
				} else if len(p.toks) > 0 {
					// check last token end? Actually if run empty and last token was word... e.g. "a"+"1"?
					// We emit words immediately, so "a1": 'a' emitted as Text word, then '1' here.
					// Chroma would emit "a1" as one. Mismatch! Fix: check if last token is Text/word ending...?
					// Simpler: include digit if last emitted token (Text/Name) ends with name char and is adjacent.
					if len(p.toks) > 0 {
						last := p.toks[len(p.toks)-1]
						_ = last
					}
				}
				break
			}
			if isPyNameStart(cc) {
				break
			}
			if _, l := matchPyOp(content, j); l > 0 {
				break
			}
			if isPyPunct(cc) {
				break
			}
			j++
		}
		// check trailing newline attach: if j<n and content[j]=='\n', include it? Only if run non-empty? Actually Text runs include \n.
		if j < n && content[j] == '\n' {
			p.addTyp("Text", content[p.pos:j+1])
			p.pos = j + 1
		} else {
			if j > p.pos {
				p.addTyp("Text", content[p.pos:j])
			} else {
				// single char (shouldn't happen; safety)
				p.addTyp("Text", content[p.pos:p.pos+1])
				j = p.pos + 1
			}
			p.pos = j
		}
		prevWord = ""
	}
	return p.toks
}

func isPyNameStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}

func isPyPunct(c byte) bool {
	switch c {
	case '(', ')', '[', ']', '{', '}', ',', ';', ':':
		return true
	}
	return false
}

func matchPyOp(s string, pos int) (string, int) {
	rest := s[pos:]
	// multi-char first (longest match)
	ops := []string{"**=", "//=", "<<=", ">>=", "**", "//", "<<", ">>", "<=", ">=", "==", "!=", "<>", ":=", "->", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "@=", "=", "+", "-", "*", "/", "%", "<", ">", "!", "&", "|", "^", "~", ".", "@"}
	for _, op := range ops {
		if strings.HasPrefix(rest, op) {
			// careful: ":" alone is punct, but ":=" is op. "." is op. "@" alone? decorator handled; matrix-mult @ is op.
			// Single "=" handled. But "=" followed by "=" handled by "==" first. Good.
			// Exclude ":" alone (punct) and "," ";" etc (not in list). Good.
			// Special: "@" alone (not decorator): op? e.g. "a @ b". Yes.
			return op, len(op)
		}
	}
	return "", 0
}

func matchPyNumber(s string, pos int) (string, int) {
	// hex/oct/bin/float/int; must not be preceded by name char or '.' (caller-ish check here)
	if pos > 0 {
		prev := s[pos-1]
		if isNameChar(prev) || prev == '.' {
			return "", 0
		}
	}
	i := pos
	n := len(s)
	if s[i] == '0' && i+1 < n && (s[i+1] == 'x' || s[i+1] == 'X') {
		j := i + 2
		for j < n && (isDigit(s[j]) || (s[j] >= 'a' && s[j] <= 'f') || (s[j] >= 'A' && s[j] <= 'F') || s[j] == '_') {
			j++
		}
		if j == i+2 {
			return "", 0
		}
		return s[pos:j], j - pos
	}
	if s[i] == '0' && i+1 < n && (s[i+1] == 'o' || s[i+1] == 'O' || s[i+1] == 'b' || s[i+1] == 'B') {
		j := i + 2
		for j < n && (isDigit(s[j]) || s[j] == '_') {
			j++
		}
		if j == i+2 {
			return "", 0
		}
		return s[pos:j], j - pos
	}
	j := i
	for j < n && (isDigit(s[j]) || s[j] == '_') {
		j++
	}
	// float?
	if j < n && s[j] == '.' && j+1 < n && isDigit(s[j+1]) {
		j++
		for j < n && (isDigit(s[j]) || s[j] == '_') {
			j++
		}
	}
	if j < n && (s[j] == 'e' || s[j] == 'E') {
		k := j + 1
		if k < n && (s[k] == '+' || s[k] == '-') {
			k++
		}
		if k < n && isDigit(s[k]) {
			for k < n && (isDigit(s[k]) || s[k] == '_') {
				k++
			}
			j = k
		}
	}
	if j < n && (s[j] == 'j' || s[j] == 'J') {
		j++
	}
	return s[pos:j], j - pos
}

// matchPyString matches [prefix]quoted string at pos. Returns (text, length).
func matchPyString(s string, pos int) (string, int) {
	i := pos
	n := len(s)
	// prefix letters
	for i < n && (s[i] == 'r' || s[i] == 'R' || s[i] == 'b' || s[i] == 'B' || s[i] == 'u' || s[i] == 'U' || s[i] == 'f' || s[i] == 'F') {
		i++
	}
	if i >= n || (s[i] != '"' && s[i] != '\'') {
		return "", 0
	}
	// must have at least quote; if prefix present, ensure it's actually prefix (letter before quote, and char before prefix is not name char?)
	if i > pos {
		if pos > 0 && isNameChar(s[pos-1]) {
			return "", 0
		}
	}
	q := s[i]
	// triple?
	if i+2 < n && s[i+1] == q && s[i+2] == q {
		end := strings.Index(s[i+3:], string([]byte{q, q, q}))
		if end < 0 {
			return s[pos:], n - pos
		}
		return s[pos : i+3+end+3], i + 3 + end + 3 - pos
	}
	j := i + 1
	for j < n && s[j] != q && s[j] != '\n' {
		if s[j] == '\\' {
			j++
		}
		j++
	}
	if j < n && s[j] == q {
		return s[pos : j+1], j + 1 - pos
	}
	// unclosed (EOL): string to EOL
	return s[pos:j], j - pos
}

// emitPyString emits a matched string, handling f-string interpolation.
func emitPyString(p *progLexer, tok string) {
	// find prefix end and quote
	i := 0
	for i < len(tok) && tok[i] != '"' && tok[i] != '\'' {
		i++
	}
	prefix := tok[:i]
	isF := strings.ContainsAny(prefix, "fF")
	q := tok[i]
	triple := false
	content := ""
	rest := tok[i:]
	if len(rest) >= 6 && rest[0] == q && rest[1] == q && rest[2] == q && strings.HasSuffix(rest, string([]byte{q, q, q})) {
		triple = true
		content = rest[3 : len(rest)-3]
	} else if len(rest) >= 2 && rest[len(rest)-1] == q {
		content = rest[1 : len(rest)-1]
	} else {
		content = rest[1:]
	}
	_ = triple
	if prefix != "" {
		p.addTyp("String", prefix)
	}
	// opening quotes
	if triple {
		p.addTyp("String", string([]byte{q, q, q}))
	} else {
		p.addTyp("String", string([]byte{q}))
	}
	if isF {
		// interpolate {expr} (no nesting)
		j := 0
		var part strings.Builder
		flush := func() {
			if part.Len() > 0 {
				p.addTyp("String", part.String())
				part.Reset()
			}
		}
		for j < len(content) {
			if content[j] == '{' {
				// {{ escape?
				if j+1 < len(content) && content[j+1] == '{' {
					part.WriteString("{{")
					j += 2
					continue
				}
				flush()
				k := strings.IndexByte(content[j:], '}')
				if k < 0 {
					part.WriteString(content[j:])
					break
				}
				p.addTyp("String", "{")
				expr := content[j+1 : j+k]
				if expr != "" {
					p.addTyp("Text", expr)
				}
				p.addTyp("String", "}")
				j = j + k + 1
			} else if content[j] == '}' && j+1 < len(content) && content[j+1] == '}' {
				part.WriteString("}}")
				j += 2
			} else {
				part.WriteByte(content[j])
				j++
			}
		}
		flush()
	} else {
		if content != "" {
			// hmm: observed `"hello"` is ONE token (not split open/content/close)!
			// For non-f strings, emit whole as one? But I already emitted prefix+open separately.
			// Restructure: for non-f, emit entire tok as one String token.
			// Undo: remove last two tokens (prefix, open) and emit whole.
			if prefix != "" {
				p.toks = p.toks[:len(p.toks)-2]
			} else {
				p.toks = p.toks[:len(p.toks)-1]
			}
			p.addTyp("String", tok)
			return
		}
	}
	// closing quotes
	if triple {
		p.addTyp("String", string([]byte{q, q, q}))
	} else {
		// only if closed (content+2+prefix == len?)
		if len(prefix)+1+len(content)+1 == len(tok) || (len(prefix)+1+len(content) < len(tok)) {
			// check last char is quote
			if tok[len(tok)-1] == q {
				p.addTyp("String", string([]byte{q}))
			}
		}
	}
}
EOF
gofmt -w proglang.go && echo ok"}

