	flush := func() {
		if part.Len() > 0 {
			p.addTyp("String", part.String())
			part.Reset()
		}
	}
	for i < n {
		c := s[i]
		if c == '`' {
			part.WriteByte('`')
			flush()
			p.pos = i + 1
			return
		}
		if c == '\\' {
			if i+1 < n {
				part.WriteByte('\\')
				part.WriteByte(s[i+1])
				i += 2
			} else {
				part.WriteByte('\\')
				i++
			}
			continue
		}
