			j := i + 2
			start := j
			for j < n && depth > 0 {
				if s[j] == '{' {
					depth++
				} else if s[j] == '}' {
					depth--
					if depth == 0 {
						break
					}
				}
				j++
			}
			expr := s[start:j]
			if expr != "" {
