	s := p.s
	n := len(p.s)
	// opening backtick included in first string part
	var part strings.Builder
	part.WriteByte('`')
	i := p.pos + 1
	flush := func() {
		if part.Len() > 0 {
			p.addTyp("String", part.String())
			part.Reset()
		}
	}
	for i < n {
		c := s[i]
		if c == '`' {
			part.WriteByte('`')
			flush()
			p.pos = i + 1
			return
		}
		if c == '\\' {
			if i+1 < n {
				part.WriteByte('\\')
				part.WriteByte(s[i+1])
				i += 2
			} else {
				part.WriteByte('\\')
				i++
			}
			continue
		}
		if c == '$' && i+1 < n && s[i+1] == '{' {
			flush()
			p.addTyp("String", "${")
			// find matching } (no nesting for simplicity... handle nesting? simple depth)
			depth := 1
			j := i + 2
			start := j
			for j < n && depth > 0 {
				if s[j] == '{' {
					depth++
				} else if s[j] == '}' {
					depth--
					if depth == 0 {
						break
					}
				}
				j++
			}
			expr := s[start:j]
			if expr != "" {
				// lex expr as JS? Simplify: emit as Name if identifier, else Text? Observed `x` -> 148 (Name).
				// For complex exprs, approximate by lexing recursively? Keep simple: if identifier -> Name else Text.
				if isJsIdent(expr) {
					p.addTyp("Name", expr)
				} else {
					p.addTyp("Text", expr)
				}
			}
			if j < n {
				p.addTyp("String", "}")
				i = j + 1
			} else {
				i = j
			}
			continue
		}
		part.WriteByte(c)
		i++
	}
	flush()
	p.pos = n
}

func isJsIdent(s string) bool {
	if s == "" {
		return false
	}
	if !(isPyNameStart(s[0]) || s[0] == '$') {
		return false
	}
	for i := 1; i < len(s); i++ {
		if !(isNameChar(s[i]) || s[i] == '$') {
			return false
		}
	}
	return true
}

// --- Go ---

func goKwClass(word string) string {
	switch word {
	case "package", "import":
		return "Keyword197"
	}
	switch word {
	case "break", "case", "chan", "const", "continue", "default", "defer",
		"else", "fallthrough", "for", "func", "go", "goto", "if",
		"interface", "map", "range", "return", "select", "struct", "switch",
		"type", "var", "true", "false", "nil", "iota":
		return "Keyword"
	}
	return ""
}

func lexGoFull(content string) []token {
	p := &progLexer{s: content}
	n := len(content)
	for p.pos < n {
		c := content[p.pos]
		if c == '\n' {
			if len(p.toks) > 0 && p.toks[len(p.toks)-1].typ == "Text" {
				p.toks[len(p.toks)-1].text += "\n"
			} else {
				p.toks = append(p.toks, token{"Text", "\n"})
			}
			p.pos++
			continue
		}
		if c == '/' && p.pos+1 < n && content[p.pos+1] == '/' {
			j := p.pos
			for j < n && content[j] != '\n' {
				j++
			}
			p.addTyp("Comment", content[p.pos:j])
			p.pos = j
			continue
		}
		if c == '/' && p.pos+1 < n && content[p.pos+1] == '*' {
			end := strings.Index(content[p.pos+2:], "*/")
			if end < 0 {
				p.addTyp("Comment", content[p.pos:])
				p.pos = n
			} else {
				p.addTyp("Comment", content[p.pos:p.pos+2+end+2])
				p.pos = p.pos + 2 + end + 2
			}
			continue
		}
		if c == '"' || c == '\'' || c == '`' {
			if c == '`' {
				// raw string (no escapes, can span lines)
				end := strings.IndexByte(content[p.pos+1:], '`')
				if end < 0 {
					p.addTyp("String", content[p.pos:])
					p.pos = n
				} else {
					p.addTyp("String", content[p.pos:p.pos+1+end+1])
					p.pos = p.pos + 1 + end + 1
				}
				continue
			}
			j := p.pos + 1
			for j < n && content[j] != c && content[j] != '\n' {
				if content[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && content[j] == c {
				p.addTyp("String", content[p.pos:j+1])
				p.pos = j + 1
			} else {
				p.addTyp("String", content[p.pos:j])
				p.pos = j
			}
			continue
		}
		if isDigit(c) {
			if num, l := matchJsNumber(content, p.pos); l > 0 {
				p.addTyp("Number", num)
				p.pos += l
				continue
			}
		}
		if isPyNameStart(c) {
			j := p.pos
			for j < n && isNameChar(content[j]) {
				j++
			}
			word := content[p.pos:j]
			if cls := goKwClass(word); cls == "Keyword" {
				p.addTyp("Keyword", word)
			} else if cls == "Keyword197" {
				p.addTyp("Operator", word)
			} else {
				p.addTyp("Name", word)
			}
			p.pos = j
			continue
		}
		if op, l := matchGoOp(content, p.pos); l > 0 {
			p.addTyp("Operator", op)
			p.pos += l
			continue
		}
		if isJsPunct(c) {
			j := p.pos
			for j < n && isJsPunct(content[j]) {
				j++
			}
			p.addTyp("Punct", content[p.pos:j])
			p.pos = j
			continue
		}
		j := p.pos
		for j < n {
			cc := content[j]
			if cc == '\n' || cc == '"' || cc == '\'' || cc == '`' {
				break
			}
			if cc == '/' && j+1 < n && (content[j+1] == '/' || content[j+1] == '*') {
				break
			}
			if isDigit(cc) {
				if content[j-1] == '.' || isNameChar(content[j-1]) {
					j++
					continue
				}
				break
			}
			if isPyNameStart(cc) {
				break
			}
			if _, l := matchGoOp(content, j); l > 0 {
				break
			}
			if isJsPunct(cc) {
				break
			}
			j++
		}
		if j < n && content[j] == '\n' {
			p.addTyp("Text", content[p.pos:j+1])
			p.pos = j + 1
		} else if j > p.pos {
			p.addTyp("Text", content[p.pos:j])
			p.pos = j
		} else {
			p.addTyp("Text", content[p.pos:p.pos+1])
			p.pos++
		}
	}
	return p.toks
}

func matchGoOp(s string, pos int) (string, int) {
	rest := s[pos:]
	ops := []string{"<<=", ">>=", "&^=", "<-", "==", "!=", "<=", ">=", "&&", "||", "<<", ">>", "&^", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "++", "--", "+", "-", "*", "/", "%", "<", ">", "!", "&", "|", "^", "~", "=", ":="}
	for _, op := range ops {
		if strings.HasPrefix(rest, op) {
			return op, len(op)
		}
	}
	return "", 0
}
