func matchJSONNumber(s string, pos int) (string, int) {
	i := pos
	n := len(s)
	if s[i] == '-' {
		i++
	}
	if i >= n || !isDigit(s[i]) {
		return "", 0
	}
	for i < n && isDigit(s[i]) {
		i++
	}
	if i < n && s[i] == '.' {
		if i+1 >= n || !isDigit(s[i+1]) {
			// "1." then non-digit: is "1" a number and "." punct? JSON requires digit after dot.
			// Return just int part? Or error? Simplify: return int part.
		} else {
			i++
			for i < n && isDigit(s[i]) {
				i++
			}
		}
	}
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		k := i + 1
		if k < n && (s[k] == '+' || s[k] == '-') {
			k++
		}
