			}
			continue
		}
		// any other char -> Error single?
		p.addTyp("Error", content[p.pos:p.pos+1])
		p.pos++
	}
	return p.toks
}

func matchJSONNumber(s string, pos int) (string, int) {
	i := pos
	n := len(s)
	if s[i] == '-' {
		i++
	}
	if i >= n || !isDigit(s[i]) {
		return "", 0
	}
	for i < n && isDigit(s[i]) {
		i++
	}
	if i < n && s[i] == '.' {
		if i+1 >= n || !isDigit(s[i+1]) {
			// "1." then non-digit: is "1" a number and "." punct? JSON requires digit after dot.
			// Return just int part? Or error? Simplify: return int part.
		} else {
			i++
			for i < n && isDigit(s[i]) {
				i++
			}
		}
	}
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		k := i + 1
		if k < n && (s[k] == '+' || s[k] == '-') {
			k++
		}
		if k < n && isDigit(s[k]) {
			for k < n && isDigit(s[k]) {
				k++
			}
			i = k
		}
	}
	return s[pos:i], i - pos
}

func appendNL(p *progLexer) {
	if len(p.toks) > 0 && p.toks[len(p.toks)-1].typ == "Text" {
		p.toks[len(p.toks)-1].text += "\n"
	} else {
		p.toks = append(p.toks, token{"Text", "\n"})
	}
}

// ---------- INI ----------

func lexINI(content string) []token {
	var toks []token
	lines := splitLinesKeep(content)
	for _, ln := range lines {
		body := strings.TrimSuffix(ln, "\n")
		hasNL := strings.HasSuffix(ln, "\n")
		emit := func(typ, s string) {
			if s != "" {
				toks = append(toks, token{typ, s})
			}
		}
		trimmed := strings.TrimSpace(body)
		if trimmed == "" {
			if hasNL {
				toks = append(toks, token{"Text", "\n"})
			}
			continue
		}
		// comment?
		ls := strings.TrimLeft(body, " \t")
		if strings.HasPrefix(ls, ";") || strings.HasPrefix(ls, "#") {
			// leading spaces?
			if len(body) > len(ls) {
				emit("Text", body[:len(body)-len(ls)])
			}
			emit("Comment", ls)
			if hasNL {
				toks = append(toks, token{"Text", "\n"})
			}
			continue
		}
		// section?
		if strings.HasPrefix(ls, "[") {
			if len(body) > len(ls) {
				emit("Text", body[:len(body)-len(ls)])
			}
			// to closing ] (or EOL?)
			if idx := strings.IndexByte(ls, ']'); idx >= 0 {
				emit("Keyword", ls[:idx+1])
				rest := ls[idx+1:]
				if rest != "" {
					emit("Text", rest)
				}
			} else {
				emit("Keyword", ls)
			}
			if hasNL {
				toks = append(toks, token{"Text", "\n"})
			}
			continue
		}
		// key = value?
		if eq := strings.IndexByte(body, '='); eq >= 0 {
			left := body[:eq]
			// leading spaces
			ltrim := strings.TrimLeft(left, " \t")
			if len(left) > len(ltrim) {
				emit("Text", left[:len(left)-len(ltrim)])
			}
			key := strings.TrimRight(ltrim, " \t")
			trailSpaces := ltrim[len(key):]
			emit("Name", key)
			emit("Text", trailSpaces)
			emit("Operator", "=")
			right := body[eq+1:]
			// leading spaces of value
			rtrim := strings.TrimLeft(right, " \t")
			if len(right) > len(rtrim) {
				emit("Text", right[:len(right)-len(rtrim)])
			}
			if rtrim != "" {
				emit("String", rtrim)
			}
			if hasNL {
				toks = append(toks, token{"Text", "\n"})
			}
			continue
		}
		// plain line -> Text?
		emit("Text", body)
		if hasNL {
			toks[len(toks)-1].text += "\n"
		}
	}
	return toks
}

func splitLinesKeep(s string) []string {
	if s == "" {
		return nil
	}
	var out []string
	start := 0
	for start < len(s) {
		idx := strings.IndexByte(s[start:], '\n')
		if idx < 0 {
			out = append(out, s[start:])
			break
		}
		out = append(out, s[start:start+idx+1])
		start = start + idx + 1
	}
	return out
}

// ---------- TOML ----------

func lexTOML(content string) []token {
	p := &progLexer{s: content}
	n := len(content)
	for p.pos < n {
		c := content[p.pos]
		if c == '\n' {
			appendNL(p)
			p.pos++
			continue
		}
		if c == '#' {
			j := p.pos
			for j < n && content[j] != '\n' {
				j++
			}
			p.addTyp("Comment", content[p.pos:j])
			p.pos = j
			continue
		}
		if c == '"' || c == '\'' {
			// basic strings (triple? single-line)
			q := c
			if p.pos+2 < n && content[p.pos+1] == q && content[p.pos+2] == q {
				// triple
				end := strings.Index(content[p.pos+3:], string([]byte{q, q, q}))
				if end < 0 {
					p.addTyp("String", content[p.pos:])
					p.pos = n
				} else {
					p.addTyp("String", content[p.pos:p.pos+3+end+3])
					p.pos = p.pos + 3 + end + 3
				}
				continue
			}
			j := p.pos + 1
			for j < n && content[j] != q && content[j] != '\n' {
				if content[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && content[j] == q {
				p.addTyp("String", content[p.pos:j+1])
				p.pos = j + 1
			} else {
				p.addTyp("String", content[p.pos:j])
				p.pos = j
			}
			continue
		}
		if isDigit(c) || (c == '-' || c == '+') {
			if num, l := matchTOMLNumber(content, p.pos); l > 0 {
				p.addTyp("Number", num)
				p.pos += l
				continue
			}
		}
		if isPyNameStart(c) {
			j := p.pos
			for j < n && (isNameChar(content[j])) {
				j++
			}
			word := content[p.pos:j]
			if word == "true" || word == "false" {
				p.addTyp("Keyword", word)
			} else {
				p.addTyp("Name", word)
			}
			p.pos = j
			continue
		}
		if c == '=' {
			p.addTyp("Punct", "=")
			p.pos++
			continue
		}
		if isJsPunct(c) || c == ':' || c == ',' {
			j := p.pos
			for j < n && (isJsPunct(content[j]) || content[j] == ':' || content[j] == ',') {
				j++
			}
			p.addTyp("Punct", content[p.pos:j])
			p.pos = j
			continue
		}
		// Text run
		j := p.pos
		for j < n {
			cc := content[j]
			if cc == '\n' || cc == '#' || cc == '"' || cc == '\'' || cc == '=' {
				break
			}
			if isDigit(cc) || cc == '-' || cc == '+' {
				// could be number; break to check
				if _, l := matchTOMLNumber(content, j); l > 0 {
					break
				}
			}
			if isPyNameStart(cc) {
				break
			}
			if isJsPunct(cc) || cc == ':' || cc == ',' {
				break
			}
			j++
		}
		if j < n && content[j] == '\n' {
			p.addTyp("Text", content[p.pos:j+1])
			p.pos = j + 1
		} else if j > p.pos {
			p.addTyp("Text", content[p.pos:j])
			p.pos = j
		} else {
			p.addTyp("Text", content[p.pos:p.pos+1])
			p.pos++
		}
	}
	return p.toks
}

func matchTOMLNumber(s string, pos int) (string, int) {
	i := pos
	n := len(s)
	if s[i] == '-' || s[i] == '+' {
		i++
	}
	if i >= n || !isDigit(s[i]) {
		return "", 0
	}
	// avoid matching inside words
	if pos > 0 && isNameChar(s[pos-1]) {
		return "", 0
	}
	for i < n && (isDigit(s[i]) || s[i] == '_') {
		i++
	}
	if i < n && s[i] == '.' && i+1 < n && isDigit(s[i+1]) {
		i++
		for i < n && (isDigit(s[i]) || s[i] == '_') {
			i++
		}
	}
	return s[pos:i], i - pos
}
