			} else {
				p.addTyp("Comment", content[p.pos:p.pos+2+end+2])
				p.pos = p.pos + 2 + end + 2
			}
			atLineStart = false
			continue
		}
		if c == '"' || c == '\'' {
			q := c
			j := p.pos + 1
			for j < n && content[j] != q && content[j] != '\n' {
				if content[j] == '\\' {
					j++
				}
				j++
			}
			if j < n && content[j] == q {
				p.addTyp("String", content[p.pos:j+1])
				p.pos = j + 1
			} else {
				p.addTyp("String", content[p.pos:j])
				p.pos = j
			}
			atLineStart = false
			continue
		}
		if c == '$' {
			// Go: Error. Others? PHP $vars handled separately (php uses different path? No - php goes through lexCLike too. Handle $vars for php.)
			p.addTyp("Error", "$")
			p.pos++
			atLineStart = false
			continue
		}
		if isDigit(c) {
			if num, l := matchJsNumber(content, p.pos); l > 0 {
				// java hack: digits after '.' -> Name(148)? Actually java `5` after `.` was 148.
				// That was '.' Punct then '5'...? Hmm, in "1.5": '1'(231) '.'(231) '5'(148).
				// So digits after '.' are Name in java. Implement: if prev is '.', Name.
				if o.numbers141 {
					p.addTyp("Number", num)
				} else {
					// java: check prev dot?
					if p.pos > 0 && content[p.pos-1] == '.' {
						p.addTyp("Name", num)
					} else {
						p.addTyp("Text", num)
					}
				}
				p.pos += l
				atLineStart = false
				continue
			}
		}
		if isPyNameStart(c) {
			j := p.pos
			for j < n && isNameChar(content[j]) {
				j++
			}
			word := content[p.pos:j]
			if o.keywords[word] {
				p.addTyp("Keyword", word)
			} else if o.import197 && (word == "import" || word == "package" || word == "from") {
				p.addTyp("Operator", word)
			} else if o.names148 {
				p.addTyp("Name", word)
			} else {
				p.addTyp("Text", word)
			}
			p.pos = j
			atLineStart = false
			continue
		}
		if op, l := matchCOp(content, p.pos); l > 0 {
			p.addTyp("Operator", op)
			p.pos += l
			atLineStart = false
			continue
		}
		if isJsPunct(c) {
			j := p.pos
			for j < n && isJsPunct(content[j]) {
				j++
			}
			p.addTyp("Punct", content[p.pos:j])
			p.pos = j
			atLineStart = false
			continue
		}
		j := p.pos
		for j < n {
			cc := content[j]
			if cc == '\n' || cc == '"' || cc == '\'' || cc == '#' || cc == '$' {
				break
			}
			if cc == '/' && j+1 < n && (content[j+1] == '/' || content[j+1] == '*') {
				break
			}
			if isDigit(cc) {
				break
			}
			if isPyNameStart(cc) {
				break
			}
			if _, l := matchCOp(content, j); l > 0 {
				break
			}
			if isJsPunct(cc) {
				break
			}
			j++
		}
		if j < n && content[j] == '\n' {
			p.addTyp("Text", content[p.pos:j+1])
			p.pos = j + 1
			atLineStart = true
		} else if j > p.pos {
			p.addTyp("Text", content[p.pos:j])
			p.pos = j
			atLineStart = false
		} else {
			p.addTyp("Text", content[p.pos:p.pos+1])
			p.pos++
			atLineStart = false
		}
		_ = atLineStart
	}
	return p.toks
}

func matchCOp(s string, pos int) (string, int) {
	rest := s[pos:]
	ops := []string{"<<=", ">>=", "...", "==", "!=", "<=", ">=", "&&", "||", "<<", ">>", "++", "--", "->", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "+", "-", "*", "/", "%", "<", ">", "!", "&", "|", "^", "~", "=", "?", ":"}
	// Note: bare "=" included; Go overrides by handling = as Punct (see lexGoFull? No - Go uses lexGoFull which has matchGoOp with := etc.)
	// For Go's bare-= quirk, Go lexer is separate (lexGoFull). This matchCOp is for c/cpp/rust/java/php.
	for _, op := range ops {
		if strings.HasPrefix(rest, op) {
			// ":" alone: in C, ":" is...? Probably Punct (231) not Operator? e.g. "case 1:"? Hmm. Ternary "a?b:c"? ":" ..." 
			// Untested. Keep as Operator? Or Punct? For "a: b" in C...? I'll keep Operator (matches :: and ?: usage).
			// Actually "::" should be one op. Add it.
			return op, len(op)
		}
	}
	if strings.HasPrefix(rest, "::") {
		return "::", 2
	}
	return "", 0
}

