				break
			}
			if cc == '.' && j+1 < n && isDigit(content[j+1]) {
				break
			}
			if cc == '.' && j+1 < n && (isPyNameStart(content[j+1]) || content[j+1] == '-') {
				break
			}
			j++
		}
		if j < n && content[j] == '\n' {
			p.addTyp("Text", content[p.pos:j+1])
			p.pos = j + 1
		} else if j > p.pos {
			p.addTyp("Text", content[p.pos:j])
			p.pos = j
		} else {
