// ---------- Fish (bash-like) ----------

var fishKeywordsExtra = map[string]bool{
	"echo": true, "set": true, "cd": true, "count": true, "printf": true,
	"test": true, "true": true, "false": true, "return": true, "exit": true,
	"break": true, "continue": true, "source": true, ".": true,
}

func lexFishFull(content string) []token {
	// Like bash but: # comments include trailing \n (unless EOF, then Text),
	// fish keywords -> 81, names -> 231 Text.
	b := &fishCtx{s: content}
	n := len(content)
	for b.pos < n {
		c := content[b.pos]
		if c == '\n' {
			if b.textSB.Len() > 0 {
				b.textSB.WriteByte('\n')
				b.flushText()
			} else {
				b.toks = append(b.toks, token{"Text", "\n"})
			}
			b.pos++
			continue
		}
		if c == '#' && isCommentStart(content, b.pos) {
			j := b.pos
			for j < n && content[j] != '\n' {
				j++
			}
			if j < n {
				// include newline
				b.addTok("Comment", content[b.pos:j+1])
				b.pos = j + 1
			} else {
				// EOF without newline: Text (fish quirk)
				b.addText(content[b.pos:j])
				b.pos = j
			}
			continue
		}
		// Reuse bash tokenizing for the rest? Simplify: handle quotes/vars/ops like bash.
		if tok, l := lexFishOne(b, content); l > 0 {
			_ = tok
			continue
		}
		// words
		if isNameChar(c) && !isDigit(c) {
			j := b.pos
			for j < n && isNameChar(content[j]) {
				j++
			}
			word := content[b.pos:j]
			if fishKw(word) {
				b.addTok("Keyword", word)
			} else {
				b.addText(word)
			}
			b.pos = j
			continue
		}
		b.addText(string([]byte{c}))
		b.pos++
	}
	b.flushText()
	return b.toks
}

type fishCtx struct {
	s      string
	pos    int
	toks   []token
	textSB strings.Builder
}

func (b *fishCtx) flushText() {
	if b.textSB.Len() > 0 {
		b.toks = append(b.toks, token{"Text", b.textSB.String()})
		b.textSB.Reset()
	}
}

func (b *fishCtx) addText(s string) { b.textSB.WriteString(s) }

func (b *fishCtx) addTok(typ, s string) {
	b.flushText()
	if s != "" {
		b.toks = append(b.toks, token{typ, s})
	}
}

func fishKw(word string) bool {
	if fishKeywordsExtra[word] {
		return true
	}
	kw, _ := fishWords()
	return kw[word]
}

// lexFishOne handles quotes/vars/numbers/ops like bash. Returns (token, len) or ("",0).
func lexFishOne(b *fishCtx, content string) (token, int) {
	n := len(content)
	c := content[b.pos]
	if c == '\'' {
		j := b.pos + 1
		for j < n && content[j] != '\'' {
			j++
		}
		if j < n {
			b.addTok("String", content[b.pos:j+1])
			b.pos = j + 1
		} else {
			b.addTok("Error", "'")
			b.pos++
		}
		return token{}, 1
	}
	if c == '"' {
		// simple dquote with $ vars (no multi-line tracking issues: allow \n inside)
		var part strings.Builder
		part.WriteByte('"')
		i := b.pos + 1
		flush := func() {
			if part.Len() > 0 {
				b.addTok("String", part.String())
				part.Reset()
			}
		}
		for i < n {
			cc := content[i]
			if cc == '"' {
				part.WriteByte('"')
				flush()
				b.pos = i + 1
				return token{}, 1
			}
			if cc == '$' {
				if name, l := matchDollarVar(content, i); l > 0 {
					flush()
					b.addTok("Text", content[i:i+l])
					i += l
					_ = name
					continue
				}
			}
			part.WriteByte(cc)
			i++
		}
		flush()
		b.pos = n
		return token{}, 1
	}
	if c == '\\' {
		if b.pos+1 < n {
			b.addTok("Number", content[b.pos:b.pos+2])
			b.pos += 2
		} else {
			b.addTok("Number", "\\")
			b.pos++
		}
		return token{}, 1
	}
	if c == '$' {
		if name, l := matchDollarVar(content, b.pos); l > 0 {
			b.addTok("Text", content[b.pos:b.pos+l])
			b.pos += l
			_ = name
			return token{}, 1
		}
		return token{}, 0
	}
	if t, l := matchBashOp(content, b.pos); l > 0 {
		b.addTok(t, content[b.pos:b.pos+l])
		b.pos += l
		return token{}, 1
	}
	if t, l := matchBashSep(content, b.pos); l > 0 {
		b.addTok(t, content[b.pos:b.pos+l])
		b.pos += l
		return token{}, 1
	}
	if isDigit(c) {
		if num, l := matchBashNumber(content, b.pos); l > 0 {
			b.addTok("Number", num)
			b.pos += l
			return token{}, 1
		}
	}
	return token{}, 0
}
